// MIT. Local browser transport for the original S3 merchant authoring controller.
import { createServer } from 'node:http';
import { constants } from 'node:fs';
import { readFile, open } from 'node:fs/promises';
import { randomBytes, timingSafeEqual, createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { openS3MerchantWorkspace } from './controller.mjs';
import { S3WorkspaceError } from './store.mjs';

const CSP = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' blob:; base-uri 'none'; frame-ancestors 'none'; form-action 'none'";
async function jsonBody(req) {
  if ((req.headers['content-type'] ?? '').split(';')[0].trim() !== 'application/json') throw new S3WorkspaceError('JSON_REQUIRED', 415);
  const chunks = []; let count = 0;
  for await (const chunk of req) { count += chunk.length; if (count > 2 * 1024 * 1024) throw new S3WorkspaceError('REQUEST_TOO_LARGE', 413); chunks.push(chunk); }
  let value; try { value = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks))); }
  catch { throw new S3WorkspaceError('INVALID_JSON', 400); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new S3WorkspaceError('JSON_OBJECT_REQUIRED', 400);
  return value;
}
const POST = {
  '/api/save': ['save', ['expectedRevision', 'operationId', 'source', 'payment', 'origin']],
  '/api/review': ['review', ['revision', 'operationId']],
  '/api/prepare': ['prepare', ['revision', 'reviewId', 'operationId']],
  '/api/stage': ['stage', ['packageId', 'releaseId', 'operationId', 'runtime']],
  '/api/console': ['openReleaseConsole', []],
};
export async function startS3MerchantWorkspace({ port = 0, releaseConsolePort, expectedAuthoringPort, ...options } = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535 ||
      releaseConsolePort !== undefined && (!Number.isInteger(releaseConsolePort) || releaseConsolePort < 0 || releaseConsolePort > 65535))
    throw new S3WorkspaceError('INVALID_PORT');
  if (port && port === releaseConsolePort) throw new S3WorkspaceError('WORKSPACE_PORT_CONFLICT');
  if (expectedAuthoringPort !== undefined && (!Number.isInteger(expectedAuthoringPort) || expectedAuthoringPort < 0 || expectedAuthoringPort > 65535))
    throw new S3WorkspaceError('WORKSPACE_BROWSER_PORT_INVALID');
  const controller = await openS3MerchantWorkspace(options);
  const priorPort = controller.authoringPort, listenPort = port || priorPort || 0;
  if (expectedAuthoringPort !== undefined && expectedAuthoringPort !== (priorPort ?? 0) ||
      listenPort && listenPort === releaseConsolePort) {
    await controller.close();
    throw new S3WorkspaceError('WORKSPACE_BROWSER_PORT_CHANGED', 409, 'Review the workspace’s current authoring and release-console ports.');
  }
  const token = randomBytes(32).toString('hex'), tokenBytes = Buffer.from(token);
  const assets = new Map();
  try {
    for (const [path, filename, type] of [['/', 'index.html', 'text/html; charset=utf-8'],
      ['/browser.mjs', 'browser.mjs', 'text/javascript; charset=utf-8'], ['/style.css', 'style.css', 'text/css; charset=utf-8']])
      assets.set(path, { bytes: await readFile(new URL(filename, import.meta.url)), type });
  } catch (error) { await controller.close(); throw error; }
  let origin, host, closing, shuttingDown = false;
  const server = createServer(async (req, res) => {
    const reply = (code, value, type = 'application/json; charset=utf-8') => {
      if (res.destroyed) return;
      const bytes = Buffer.isBuffer(value) ? value : Buffer.from(JSON.stringify(value));
      res.writeHead(code, { 'content-type': type, 'content-length': String(bytes.length),
        'cache-control': 'no-store', 'content-security-policy': CSP, 'x-content-type-options': 'nosniff',
        'referrer-policy': 'no-referrer', 'cross-origin-resource-policy': 'same-origin' });
      res.end(req.method === 'HEAD' ? undefined : bytes);
    };
    try {
      if (req.headers.host !== host || req.headers.origin && req.headers.origin !== origin ||
          ['cross-site', 'same-site'].includes(req.headers['sec-fetch-site'])) throw new S3WorkspaceError('LOCAL_ORIGIN_REQUIRED', 403);
      if (!req.url?.startsWith('/') || req.url.startsWith('//')) throw new S3WorkspaceError('INVALID_TARGET', 400);
      const target = new URL(req.url, origin);
      if (['GET', 'HEAD'].includes(req.method) && !target.search && assets.has(target.pathname)) {
        const asset = assets.get(target.pathname); reply(200, asset.bytes, asset.type); return;
      }
      const supplied = Buffer.from(req.headers['x-s3-workspace-token'] ?? '');
      if (supplied.length !== tokenBytes.length || !timingSafeEqual(supplied, tokenBytes)) throw new S3WorkspaceError('WORKSPACE_TOKEN_REQUIRED', 401);
      if (shuttingDown) throw new S3WorkspaceError('WORKSPACE_CLOSING', 409);
      if (req.method === 'POST' && POST[target.pathname] && !target.search) {
        if (req.headers.origin !== origin) throw new S3WorkspaceError('SAME_ORIGIN_ACTION_REQUIRED', 403);
        const [method, keys] = POST[target.pathname], body = await jsonBody(req);
        if (Object.keys(body).some(key => !keys.includes(key))) throw new S3WorkspaceError('UNKNOWN_ACTION_FIELD', 400);
        reply(200, await controller[method](body)); return;
      }
      if (req.method !== 'GET') throw new S3WorkspaceError('ACTION_NOT_FOUND', 404);
      const query = Object.fromEntries(target.searchParams);
      if (Object.keys(query).length !== [...target.searchParams].length) throw new S3WorkspaceError('DUPLICATE_PARAMETER', 400);
      const routes = {
        '/api/status': ['status', []], '/api/history': ['history', ['beforeRevision', 'limit']],
        '/api/revision': ['revision', ['revision']], '/api/review': ['getReview', ['reviewId']],
        '/api/package': ['getPackage', ['packageId']], '/api/customer': ['exportCustomer', ['releaseId']],
        '/api/customer/file': ['readCustomerFile', ['releaseId', 'file', 'offset', 'limit', 'expectedSha256']],
      };
      const route = routes[target.pathname];
      if (!route || Object.keys(query).some(key => !route[1].includes(key))) throw new S3WorkspaceError('ACTION_NOT_FOUND', 404);
      for (const key of ['revision', 'beforeRevision', 'limit', 'offset']) if (query[key] !== undefined) {
        if (!/^(0|[1-9][0-9]*)$/.test(query[key]) || !Number.isSafeInteger(Number(query[key]))) throw new S3WorkspaceError('INVALID_NUMBER', 400);
        query[key] = Number(query[key]);
      }
      reply(200, await controller[route[0]](query));
    } catch (error) {
      reply(error.status ?? (['RELEASE_CONFLICT', 'RELEASE_BUSY', 'EEXIST'].includes(error.code) ? 409 : 422),
        { error: error.code ?? 'S3_WORKSPACE_ERROR', message: error.message });
    }
  });
  server.requestTimeout = 150000; server.headersTimeout = 10000; server.keepAliveTimeout = 2000;
  try { await new Promise((done, fail) => { server.once('error', fail); server.listen(listenPort, '127.0.0.1', done); }); }
  catch (error) { await controller.close(); throw error; }
  origin = new URL('http://127.0.0.1:' + server.address().port).origin; host = new URL(origin).host;
  const close = () => closing ??= (async () => {
    shuttingDown = true;
    try { await controller.close(); }
    finally { await new Promise((done, fail) => { server.close(error => error ? fail(error) : done()); server.closeIdleConnections?.(); }); }
  })();
  let releaseConsole = null;
  try {
    controller.retainAuthoringPort({ port: server.address().port, expectedPort: priorPort });
    if (releaseConsolePort !== undefined)
      releaseConsole = await controller.openReleaseConsole({ port: releaseConsolePort });
  } catch (error) { await close(); throw error; }
  return { controller, server, origin, url: origin + '/#' + token, token, releaseConsole, close };
}

const HELP = `S3 merchant workspace
  node server.mjs --state PRIVATE_DIRECTORY [--port 0] [--release-store EXISTING_OR_NEW_STORE]
    [--source PRIVATE_SOURCE.json --payment PUBLIC_TERMS.json --origin HTTPS_ORIGIN]
    [--release-console-port 0] [--expected-workspace-id new|ORIGINAL_UUID]
    [--expected-authoring-port PREVIOUS_PORT_OR_0]
    [--expected-source-sha256 SHA256 --expected-payment-sha256 SHA256]

Source/payment/origin import the first revision only. Reopen the same --state
without the original files. The original AWS provider stays in this process.
The printed private local URL opens source, product, price and release authoring.
--release-console-port also opens the original release console in this same
managed session; stopping the workspace drains that console and its owned seller.
Port 0 reuses this workspace's saved authoring port after its first launch, keeping
its browser draft and pending request recovery on the same origin.
`;
async function importFile(path, expectedSha256) {
  const filename = resolve(path);
  const handle = await open(filename, constants.O_RDONLY | constants.O_NOFOLLOW);
  let bytes;
  try {
    const before = await handle.stat({ bigint: true });
    if (!before.isFile() || before.size > 1048576n) throw new S3WorkspaceError('IMPORT_TOO_LARGE');
    bytes = await handle.readFile();
    const after = await handle.stat({ bigint: true });
    if (BigInt(bytes.length) !== before.size || before.size !== after.size ||
        before.mtimeNs !== after.mtimeNs || before.ctimeNs !== after.ctimeNs)
      throw new S3WorkspaceError('IMPORT_CHANGED', 409);
  } finally { await handle.close(); }
  const sha256 = createHash('sha256').update(bytes).digest('hex');
  if (expectedSha256 !== undefined && expectedSha256 !== sha256)
    throw new S3WorkspaceError('IMPORT_CHANGED', 409, 'The original import file changed after review.');
  let value;
  try { value = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); }
  catch { throw new S3WorkspaceError('IMPORT_JSON_REQUIRED'); }
  return { path: filename, sha256, value };
}
export async function main(args = process.argv.slice(2)) {
  if (!args.length || args.length === 1 && ['--help', '-h'].includes(args[0])) { process.stdout.write(HELP); return; }
  const flags = {}, known = ['--state', '--port', '--release-store', '--source', '--payment', '--origin',
    '--release-console-port', '--expected-workspace-id', '--expected-authoring-port', '--expected-source-sha256', '--expected-payment-sha256'];
  for (let index = 0; index < args.length; index += 2) {
    const [key, value] = args.slice(index, index + 2);
    if (!known.includes(key) || !value || value.startsWith('--') || Object.hasOwn(flags, key)) throw new S3WorkspaceError('INVALID_OPTIONS', 400, HELP);
    flags[key] = value;
  }
  if (!flags['--state']) throw new S3WorkspaceError('STATE_REQUIRED', 400, HELP);
  const importCount = ['--source', '--payment', '--origin'].filter(key => flags[key]).length;
  if (importCount !== 0 && importCount !== 3) throw new S3WorkspaceError('COMPLETE_IMPORT_REQUIRED', 400, HELP);
  for (const key of ['--expected-source-sha256', '--expected-payment-sha256'])
    if (flags[key] !== undefined && (importCount !== 3 || !/^[a-f0-9]{64}$/.test(flags[key])))
      throw new S3WorkspaceError('EXPECTED_IMPORT_HASH_INVALID');
  const port = key => {
    if (flags[key] === undefined) return undefined;
    if (!/^(0|[1-9][0-9]*)$/.test(flags[key])) throw new S3WorkspaceError('INVALID_PORT');
    const value = Number(flags[key]);
    if (!Number.isSafeInteger(value) || value > 65535) throw new S3WorkspaceError('INVALID_PORT');
    return value;
  };
  let source, payment;
  if (importCount) [source, payment] = await Promise.all([
    importFile(flags['--source'], flags['--expected-source-sha256']),
    importFile(flags['--payment'], flags['--expected-payment-sha256']),
  ]);
  const session = await startS3MerchantWorkspace({ directory: resolve(flags['--state']),
    ...(flags['--release-store'] ? { releaseStore: resolve(flags['--release-store']) } : {}),
    port: port('--port') ?? 0, releaseConsolePort: port('--release-console-port'),
    expectedAuthoringPort: port('--expected-authoring-port'),
    expectedWorkspaceId: flags['--expected-workspace-id'],
    ...(importCount ? { initial: { source: source.value, payment: payment.value, origin: flags['--origin'] } } : {}) });
  const stop = () => { void session.close().then(() => { process.exitCode = 0; }, error => { process.stderr.write(error.message + '\n'); process.exitCode = 1; }); };
  for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, stop);
  process.stdout.write(JSON.stringify({
    schema: 'stellar-forge.s3-workspace-startup.v1', status: 'S3_MERCHANT_WORKSPACE_READY',
    workspace: session.url, directory: session.controller.directory, workspaceId: session.controller.workspaceId,
    releaseStore: session.controller.releaseStore, releaseConsole: session.releaseConsole,
    authoringPort: session.server.address().port,
    initial: importCount ? { sourceFile: source.path, sourceSha256: source.sha256,
      paymentFile: payment.path, paymentSha256: payment.sha256, origin: flags['--origin'] } : null,
  }) + '\n');
  return session;
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  main().catch(error => { process.stderr.write(error.message + '\n'); process.exitCode = 1; });

// MIT. Native transactional authoring history for the original S3 merchant.
import { DatabaseSync } from 'node:sqlite';
import { mkdir, realpath, lstat, chmod } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export class S3WorkspaceError extends Error {
  constructor(code, status = 422, message = code) {
    super(message); this.name = 'S3WorkspaceError'; this.code = code; this.status = status;
  }
}
export const encode = value => JSON.stringify(value, null, 2) + '\n';
export const sha256 = value => createHash('sha256').update(value).digest('hex');
const normalized = value => Array.isArray(value) ? value.map(normalized) : value && typeof value === 'object'
  ? Object.fromEntries(Object.keys(value).sort().map(key => [key, normalized(value[key])])) : value;
export const fingerprint = value => sha256(JSON.stringify(normalized(value)));
export function operationId(value) {
  if (typeof value !== 'string' || !/^[a-z][a-z0-9-]{7,79}$/.test(value))
    throw new S3WorkspaceError('OPERATION_ID_REQUIRED', 422, 'Use an operation ID of 8–80 lowercase letters, digits and hyphens, starting with a letter.');
  return value;
}
export function revisionNumber(value, allowZero = false) {
  if (!Number.isSafeInteger(value) || value < (allowZero ? 0 : 1))
    throw new S3WorkspaceError('INVALID_REVISION');
  return value;
}
const draftRow = row => row ? { revision: row.revision, operationId: row.operation_id,
  savedAt: row.saved_at, sourceSha256: row.source_sha256, paymentSha256: row.payment_sha256,
  origin: row.origin, source: JSON.parse(row.source), payment: JSON.parse(row.payment) } : null;
const operationRow = row => row ? { operationId: row.id, kind: row.kind, inputSha256: row.input_sha256,
  input: JSON.parse(row.input), context: row.context ? JSON.parse(row.context) : null,
  state: row.state, createdAt: row.created_at, updatedAt: row.updated_at,
  result: row.result ? JSON.parse(row.result) : null, error: row.error } : null;

async function regularOrMissing(path) {
  try { if (!(await lstat(path)).isFile()) throw new S3WorkspaceError('WORKSPACE_FILE_INVALID'); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
}

export const S3_WORKSPACE_INSPECTION_SCHEMA = 'stellar-forge.s3-workspace-inspection.v1';
const WORKSPACE_UUID = /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/;
const CONTENT_HASH = /^[a-f0-9]{64}$/;
const browserPort = value => value === null || value === undefined ? null :
  typeof value === 'string' && /^(?:[1-9][0-9]*)$/.test(value) && Number(value) <= 65535 ? Number(value) :
    (() => { throw new S3WorkspaceError('WORKSPACE_BROWSER_PORT_INVALID'); })();

/** Read the original identity and current revision without taking its writer lease. */
export async function inspectS3WorkspaceStore(directory, { allowMissing = false } = {}) {
  if (typeof directory !== 'string' || !directory || directory.includes('\0') ||
      typeof allowMissing !== 'boolean') throw new S3WorkspaceError('WORKSPACE_DIRECTORY_REQUIRED');
  const root = resolve(directory), filename = join(root, 'workspace.sqlite');
  const empty = { schema: S3_WORKSPACE_INSPECTION_SCHEMA, state: 'NEW', directory: root,
    workspaceId: null, releaseStore: null, authoringPort: null, revision: 0, latest: null, database: null };
  let folder, before;
  try { folder = await lstat(root); }
  catch (error) { if (allowMissing && error.code === 'ENOENT') return empty; throw error; }
  if (!folder.isDirectory() || folder.isSymbolicLink() || await realpath(root) !== root)
    throw new S3WorkspaceError('WORKSPACE_DIRECTORY_INVALID');
  try { before = await lstat(filename); }
  catch (error) { if (allowMissing && error.code === 'ENOENT') return empty; throw error; }
  if (!before.isFile() || before.isSymbolicLink() || await realpath(filename) !== filename)
    throw new S3WorkspaceError('WORKSPACE_FILE_INVALID');
  let db, result;
  try {
    db = new DatabaseSync(filename, { readOnly: true });
    db.exec('PRAGMA busy_timeout=1000; BEGIN');
    const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map(row => row.name);
    if (!['metadata', 'revisions', 'reviews', 'operations'].every(name => tables.includes(name)))
      throw new S3WorkspaceError('WORKSPACE_STORE_INVALID');
    const value = key => db.prepare('SELECT value FROM metadata WHERE key=?').get(key)?.value ?? null;
    const workspaceId = value('workspaceId'), releaseStore = value('releaseStore'),
      authoringPort = browserPort(value('authoringPort'));
    if (!WORKSPACE_UUID.test(workspaceId ?? '') ||
        releaseStore !== null && (typeof releaseStore !== 'string' || !releaseStore ||
          releaseStore.includes('\0') || resolve(releaseStore) !== releaseStore))
      throw new S3WorkspaceError('WORKSPACE_STORE_INVALID');
    const row = db.prepare('SELECT revision,source_sha256,payment_sha256,origin,saved_at FROM revisions ORDER BY revision DESC LIMIT 1').get();
    if (row && (!Number.isSafeInteger(row.revision) || row.revision < 1 ||
        !CONTENT_HASH.test(row.source_sha256) || !CONTENT_HASH.test(row.payment_sha256) ||
        typeof row.origin !== 'string' || typeof row.saved_at !== 'string'))
      throw new S3WorkspaceError('WORKSPACE_STORE_INVALID');
    result = { schema: S3_WORKSPACE_INSPECTION_SCHEMA, state: 'READY', directory: root,
      workspaceId, releaseStore, authoringPort, revision: row?.revision ?? 0,
      latest: row ? { revision: row.revision, sourceSha256: row.source_sha256,
        paymentSha256: row.payment_sha256, origin: row.origin, savedAt: row.saved_at } : null,
      database: { path: filename, kind: 's3-workspace-store', exists: true, dev: before.dev, ino: before.ino } };
    db.exec('COMMIT');
  } catch (error) {
    if (error instanceof S3WorkspaceError) throw error;
    throw new S3WorkspaceError('WORKSPACE_STORE_INVALID', 409, 'Select an original S3 merchant workspace or a new private directory.');
  } finally { db?.close(); }
  const after = await lstat(filename);
  if (!after.isFile() || after.isSymbolicLink() || after.dev !== before.dev || after.ino !== before.ino)
    throw new S3WorkspaceError('WORKSPACE_IDENTITY_CHANGED', 409);
  return result;
}

/** SQLite supplies the revision compare-and-swap and crash-released operation lock. */
export async function openS3WorkspaceStore(directory, { expectedWorkspaceId } = {}) {
  if (expectedWorkspaceId !== undefined && expectedWorkspaceId !== 'new' &&
      !WORKSPACE_UUID.test(expectedWorkspaceId ?? ''))
    throw new S3WorkspaceError('EXPECTED_WORKSPACE_ID_INVALID');
  if (expectedWorkspaceId && expectedWorkspaceId !== 'new') {
    const original = await lstat(join(resolve(directory), 'workspace.sqlite'));
    if (!original.isFile() || original.isSymbolicLink()) throw new S3WorkspaceError('WORKSPACE_FILE_INVALID');
  }
  await mkdir(resolve(directory), { recursive: true, mode: 0o700 });
  const root = await realpath(resolve(directory)); await chmod(root, 0o700);
  const filename = join(root, 'workspace.sqlite'), lockfile = join(root, 'operations.sqlite');
  await regularOrMissing(filename); await regularOrMissing(lockfile);
  const db = new DatabaseSync(filename);
  try {
    await chmod(filename, 0o600);
    db.exec('PRAGMA busy_timeout=1000; PRAGMA foreign_keys=ON; PRAGMA synchronous=FULL; BEGIN IMMEDIATE');
    db.exec(`
    CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY,value TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS revisions (
      revision INTEGER PRIMARY KEY,operation_id TEXT NOT NULL UNIQUE,input_sha256 TEXT NOT NULL,
      source TEXT NOT NULL,payment TEXT NOT NULL,origin TEXT NOT NULL,
      source_sha256 TEXT NOT NULL,payment_sha256 TEXT NOT NULL,saved_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS reviews (
      id TEXT PRIMARY KEY,revision INTEGER NOT NULL REFERENCES revisions(revision),
      selected_source TEXT NOT NULL,description TEXT NOT NULL,service TEXT NOT NULL,
      source_sha256 TEXT NOT NULL,selection_sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS operations (
      id TEXT PRIMARY KEY,kind TEXT NOT NULL,input_sha256 TEXT NOT NULL,input TEXT NOT NULL,context TEXT,
      state TEXT NOT NULL,result TEXT,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);`);
    const priorId = db.prepare('SELECT value FROM metadata WHERE key=?').get('workspaceId')?.value;
    if (priorId !== undefined && !WORKSPACE_UUID.test(priorId))
      throw new S3WorkspaceError('WORKSPACE_STORE_INVALID');
    if (expectedWorkspaceId === 'new' && priorId !== undefined ||
        expectedWorkspaceId && expectedWorkspaceId !== 'new' && priorId !== expectedWorkspaceId)
      throw new S3WorkspaceError('WORKSPACE_IDENTITY_CHANGED', 409,
        'The original S3 workspace changed after review. Reopen its current identity before starting.');
    if (priorId === undefined)
      db.prepare('INSERT INTO metadata(key,value) VALUES (?,?)').run('workspaceId', randomUUID());
    db.exec('COMMIT');
  } catch (error) {
    try { if (db.isTransaction) db.exec('ROLLBACK'); }
    finally { db.close(); }
    throw error;
  }
  let closed = false;
  const transaction = fn => {
    db.exec('BEGIN IMMEDIATE');
    try { const result = fn(); db.exec('COMMIT'); return result; }
    catch (error) { db.exec('ROLLBACK'); throw error; }
  };
  const latest = () => draftRow(db.prepare('SELECT * FROM revisions ORDER BY revision DESC LIMIT 1').get());
  const getOperation = id => operationRow(db.prepare('SELECT * FROM operations WHERE id=?').get(operationId(id)));
  const review = id => {
    if (typeof id !== 'string' || !/^[a-f0-9]{64}$/.test(id)) throw new S3WorkspaceError('INVALID_REVIEW_ID');
    const row = db.prepare('SELECT * FROM reviews WHERE id=?').get(id);
    if (!row) throw new S3WorkspaceError('REVIEW_NOT_FOUND', 404);
    return { reviewId: row.id, revision: row.revision, createdAt: row.created_at,
      sourceSha256: row.source_sha256, selectionSha256: row.selection_sha256,
      selectedSource: JSON.parse(row.selected_source), description: JSON.parse(row.description), service: JSON.parse(row.service) };
  };
  const store = {
    directory: root, workspaceId: db.prepare('SELECT value FROM metadata WHERE key=?').get('workspaceId').value,
    latest, getOperation, review,
    authoringPort() {
      return browserPort(db.prepare('SELECT value FROM metadata WHERE key=?').get('authoringPort')?.value);
    },
    retainAuthoringPort({ port, expectedPort }) {
      if (!Number.isInteger(port) || port < 1 || port > 65535 ||
          expectedPort !== null && (!Number.isInteger(expectedPort) || expectedPort < 1 || expectedPort > 65535))
        throw new S3WorkspaceError('WORKSPACE_BROWSER_PORT_INVALID');
      return transaction(() => {
        const current = store.authoringPort();
        if (current !== expectedPort) throw new S3WorkspaceError('WORKSPACE_BROWSER_PORT_CHANGED', 409,
          'The workspace browser listener changed. Reopen its current launch review.');
        if (current !== port)
          db.prepare('INSERT INTO metadata(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value')
            .run('authoringPort', String(port));
        return port;
      });
    },
    metadata(key, value) {
      return transaction(() => {
        const prior = db.prepare('SELECT value FROM metadata WHERE key=?').get(key)?.value;
        if (value !== undefined && prior !== undefined && prior !== value)
          throw new S3WorkspaceError('WORKSPACE_CONFIGURATION_CONFLICT', 409, 'Reopen this workspace with its original release store.');
        if (value !== undefined) db.prepare('INSERT OR IGNORE INTO metadata(key,value) VALUES (?,?)').run(key, value);
        return prior ?? value;
      });
    },
    revision(value) {
      const result = draftRow(db.prepare('SELECT * FROM revisions WHERE revision=?').get(revisionNumber(value)));
      if (!result) throw new S3WorkspaceError('REVISION_NOT_FOUND', 404);
      return result;
    },
    history({ beforeRevision, limit = 50 } = {}) {
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new S3WorkspaceError('INVALID_PAGE_SIZE');
      if (beforeRevision !== undefined) revisionNumber(beforeRevision);
      const rows = db.prepare('SELECT * FROM revisions WHERE revision<? ORDER BY revision DESC LIMIT ?')
        .all(beforeRevision ?? Number.MAX_SAFE_INTEGER, limit + 1);
      return { revisions: rows.slice(0, limit).map(row => {
        const { source, payment, ...summary } = draftRow(row); return summary;
      }), nextBeforeRevision: rows.length > limit ? rows[limit - 1].revision : null };
    },
    save({ expectedRevision, operationId: id, source, payment, origin }) {
      revisionNumber(expectedRevision, true); operationId(id);
      const inputSha = fingerprint({ source, payment, origin });
      return transaction(() => {
        const prior = db.prepare('SELECT * FROM revisions WHERE operation_id=?').get(id);
        if (prior) {
          if (prior.input_sha256 !== inputSha) throw new S3WorkspaceError('OPERATION_CONTENT_CONFLICT', 409);
          return draftRow(prior);
        }
        const head = latest()?.revision ?? 0;
        if (head !== expectedRevision) throw new S3WorkspaceError('REVISION_CONFLICT', 409, 'Another editor saved this workspace. Reopen the current revision and reconcile your draft.');
        const sourceText = encode(source), paymentText = encode(payment);
        db.prepare('INSERT INTO revisions VALUES (?,?,?,?,?,?,?,?,?)').run(head + 1, id, inputSha,
          sourceText, paymentText, origin, sha256(sourceText), sha256(paymentText), new Date().toISOString());
        return latest();
      });
    },
    saveReview({ revision, selectedSource, description, service, sourceSha256, operationId: actionId }) {
      const selectionSha256 = sha256(encode(selectedSource));
      const id = fingerprint({ revision, selectionSha256, description, service });
      operationId(actionId);
      return transaction(() => {
        const operation = getOperation(actionId);
        if (!operation || operation.kind !== 'REVIEW' || operation.input.revision !== revision)
          throw new S3WorkspaceError('REVIEW_OPERATION_CONFLICT', 409);
        db.prepare('INSERT OR IGNORE INTO reviews VALUES (?,?,?,?,?,?,?,?)').run(id, revision,
          encode(selectedSource), encode(description), encode(service), sourceSha256, selectionSha256, new Date().toISOString());
        store.finishOperation(actionId, { reviewId: id, revision });
        return review(id);
      });
    },
    reviews() {
      return db.prepare('SELECT id,revision,source_sha256,selection_sha256,created_at FROM reviews ORDER BY created_at DESC').all()
        .map(row => ({ reviewId: row.id, revision: row.revision, sourceSha256: row.source_sha256,
          selectionSha256: row.selection_sha256, createdAt: row.created_at }));
    },
    beginOperation(id, kind, input, context = null) {
      operationId(id); const digest = fingerprint(input);
      return transaction(() => {
        const existing = getOperation(id);
        if (existing) {
          if (existing.kind !== kind || existing.inputSha256 !== digest)
            throw new S3WorkspaceError('OPERATION_CONTENT_CONFLICT', 409);
          return existing;
        }
        const now = new Date().toISOString();
        db.prepare('INSERT INTO operations VALUES (?,?,?,?,?,?,?,?,?,?)').run(id, kind, digest,
          encode(input), context ? encode(context) : null, 'RUNNING', null, null, now, now);
        return getOperation(id);
      });
    },
    finishOperation(id, result) {
      db.prepare('UPDATE operations SET state=?,result=?,error=NULL,updated_at=? WHERE id=?')
        .run('COMPLETE', encode(result), new Date().toISOString(), operationId(id));
      return result;
    },
    failOperation(id, error) {
      db.prepare('UPDATE operations SET state=?,error=?,updated_at=? WHERE id=? AND state<>?')
        .run('INTERRUPTED', String(error.code ?? 'WORKSPACE_OPERATION_FAILED'), new Date().toISOString(), operationId(id), 'COMPLETE');
    },
    operations() {
      return db.prepare('SELECT * FROM operations ORDER BY created_at DESC').all().map(row => {
        const { input, context, inputSha256, ...summary } = operationRow(row); return summary;
      });
    },
    async lockOperation(fn) {
      await regularOrMissing(lockfile);
      const lock = new DatabaseSync(lockfile);
      try {
        await chmod(lockfile, 0o600);
        try { lock.exec('PRAGMA busy_timeout=0; BEGIN EXCLUSIVE;'); }
        catch (cause) { throw new S3WorkspaceError('WORKSPACE_BUSY', 409, 'Another native S3 authoring operation is running. Refresh its saved result.'); }
        return await fn();
      } finally { lock.close(); }
    },
    close() { if (!closed) { closed = true; db.close(); } },
  };
  return store;
}

// MIT. The installed SDMX entrypoint uses the original Python workspace and native seller/buyer.
import { spawn } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

export async function main(args = process.argv.slice(2)) {
  if (args[0] === 'macrobond') return (await import('./macrobond/cli.mjs')).main(args.slice(1));
  if (args[0] === 'merchant') return (await import('./merchant.mjs')).main(args.slice(1));
  if (args[0] === 'buyer') return (await import('./customer.mjs')).main(args.slice(1));
  const executable = process.env.SF30_SDMX_PYTHON || process.env.SF30_XML_PYTHON ||
    (process.platform === 'win32' ? 'python' : 'python3');
  const child = spawn(executable, ['-B', fileURLToPath(new URL('./cli.py', import.meta.url)), ...args], {
    stdio: 'inherit', shell: false,
    env: { ...process.env, SF30_SDMX_NODE: process.execPath, SF30_XML_NODE: process.execPath },
  });
  const interrupt = () => child.kill('SIGINT');
  const terminate = () => child.kill('SIGTERM');
  process.on('SIGINT', interrupt); process.on('SIGTERM', terminate);
  try {
    const code = await new Promise((resolveCode, reject) => {
      child.once('error', () => reject(new Error('Python 3.11+ is required; set SF30_SDMX_PYTHON to its executable.')));
      child.once('close', (code, signal) => resolveCode(code ?? (signal === 'SIGTERM' ? 143 : 130)));
    });
    process.exitCode = code;
  } finally {
    process.off('SIGINT', interrupt); process.off('SIGTERM', terminate);
  }
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => {
    process.stderr.write(JSON.stringify({ error: error.code ?? 'SDMX', message: error.message }) + '\n');
    process.exitCode = 1;
  });

// MIT. SDMX edition selections through the ORIGINAL SF88 buyer and receiving flow.
import { constants } from 'node:fs';
import { open, link, rm, mkdir, lstat } from 'node:fs/promises';
import { createHash, randomUUID } from 'node:crypto';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { readSdmxMerchant } from './merchant.mjs';
import { readDatasetBuyerOffer, prepareDatasetBuyer } from '../dataset-refresh/buyer-handoff.mjs';

const fault = (code, message, status = 400) => Object.assign(new Error(message), { code, status });
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
function queryString(query) {
  if (!object(query) || Object.entries(query).some(([key, value]) =>
      typeof value !== 'string' || ['snapshot', 'cursor'].includes(key)))
    throw fault('SDMX_BUYER_QUERY_INVALID', 'Supply original first-page string query parameters; the selected edition supplies snapshot.');
  const value = new URLSearchParams(Object.entries(query)).toString();
  if (value.length > 8192) throw fault('SDMX_BUYER_QUERY_INVALID', 'The query exceeds the native buyer limit.');
  return value;
}
export async function reviewSdmxBuyer({ directory, seller, query = {} } = {}) {
  const release = await readSdmxMerchant(directory);
  const review = await readDatasetBuyerOffer({ seller, resource: release.manifest.resource,
    snapshot: release.manifest.snapshot, query: queryString(query) });
  return { ...review, edition: { release: release.manifest.id, project: release.manifest.project,
    snapshot: release.manifest.snapshot } };
}
async function saveExact(path, bytes) {
  const directory = dirname(path);
  await mkdir(directory, { recursive: true, mode: 0o700 });
  const info = await lstat(directory);
  if (!info.isDirectory() || info.isSymbolicLink())
    throw fault('SDMX_BUYER_DIRECTORY_INVALID', 'Select an original private buyer directory.');
  const temporary = join(directory, '.sdmx-buyer-' + randomUUID());
  let recovered = false;
  try {
    const handle = await open(temporary, 'wx', 0o600);
    try { await handle.writeFile(bytes); await handle.sync(); } finally { await handle.close(); }
    try { await link(temporary, path); }
    catch (error) {
      if (error.code !== 'EEXIST') throw error;
      const retained = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
      try {
        const before = await retained.stat({ bigint: true });
        if (!before.isFile() || before.size !== BigInt(bytes.length))
          throw fault('SDMX_BUYER_CONFIG_CONFLICT', 'The selected output contains a different original buyer configuration.', 409);
        const existing = await retained.readFile();
        const after = await retained.stat({ bigint: true });
        if (!existing.equals(bytes) || before.mtimeNs !== after.mtimeNs || before.ctimeNs !== after.ctimeNs)
          throw fault('SDMX_BUYER_CONFIG_CONFLICT', 'The selected output contains a different original buyer configuration.', 409);
        recovered = true;
      } finally { await retained.close(); }
    }
    const directoryHandle = await open(directory, constants.O_RDONLY);
    try { await directoryHandle.sync(); } finally { await directoryHandle.close(); }
  } finally { await rm(temporary, { force: true }); }
  return { path, bytes: bytes.length, sha256: digest(bytes), recovered };
}
/** Reload the original live offer immediately before its reviewed preparation.
 * The result is the original SF88 draft. Existing operator setup supplies the
 * account, reservation policy and signer; this bridge never creates a signer. */
export async function prepareSdmxBuyer({ directory, seller, query = {}, intentId,
  acceptIndex, offerSha256, destination } = {}) {
  const review = await reviewSdmxBuyer({ directory, seller, query });
  const prepared = prepareDatasetBuyer(review, { intentId, acceptIndex, offerSha256 });
  const bytes = Buffer.from(prepared.configText, 'utf8');
  if (digest(bytes) !== prepared.configSha256)
    throw fault('SDMX_BUYER_CONFIG_CHANGED', 'The original buyer preparation returned inconsistent file identity.', 409);
  if (typeof destination !== 'string' || !destination)
    throw new TypeError('Choose a private output file for the original buyer configuration.');
  const saved = await saveExact(resolve(destination), bytes);
  return { ...prepared, edition: review.edition, saved };
}

const HELP = [
  'SDMX original buyer and receiving',
  'offer --release RELEASE_DIR --seller http://127.0.0.1:PORT [--query JSON_STRING_PARAMETERS]',
  'prepare --release RELEASE_DIR --seller http://127.0.0.1:PORT [--query JSON_STRING_PARAMETERS]',
  '        --intent ID --accept-index INDEX --offer-sha SHA256 --out PRIVATE_BUYER.json',
  '',
  'The following commands use the original SF88 dataset CLI unchanged:',
  'init --session PRIVATE_SESSION --config CONFIG --max-pages N --max-total-atomic AMOUNT',
  '     [--snapshot SHA256] [--max-rows N] [--max-page-bytes N]',
  '     Use --workspace ORIGINAL_OPERATOR_WORKSPACE instead of --config to reuse its account.',
  'status|run|recover --session PRIVATE_SESSION',
  'export|deliver --session PRIVATE_SESSION --out DESTINATION',
  'accounting|finalize --session PRIVATE_SESSION [original SF88 options]',
  '',
  'Each live offer is read from the original seller; preparation pins the selected SDMX snapshot.',
  'run retains original per-page quote review, operator reservation and native buyer execution.',
  'recover reads the original attempt; deliver retains the original dataset data-room files.',
].join('\n') + '\n';
function options(args) {
  const [action, ...tokens] = args;
  const allowed = action === 'offer' ? ['--release', '--seller', '--query']
    : ['--release', '--seller', '--query', '--intent', '--accept-index', '--offer-sha', '--out'];
  const flags = {};
  if (tokens.length % 2) throw new TypeError('Each buyer option requires its value.');
  for (let i = 0; i < tokens.length; i += 2) {
    if (!allowed.includes(tokens[i]) || Object.hasOwn(flags, tokens[i]) ||
        !tokens[i + 1] || tokens[i + 1].startsWith('--'))
      throw new TypeError('Unknown, repeated or missing SDMX buyer option.');
    flags[tokens[i]] = tokens[i + 1];
  }
  const required = name => {
    if (!flags[name]) throw new TypeError(name + ' is required.');
    return flags[name];
  };
  let query;
  try {
    if ((flags['--query'] ?? '{}').length > 8192) throw new Error();
    query = JSON.parse(flags['--query'] ?? '{}');
  } catch { throw fault('SDMX_BUYER_QUERY_INVALID', 'Use a JSON object of original string query parameters.'); }
  const result = { directory: required('--release'), seller: required('--seller'), query };
  if (action === 'prepare') {
    const index = required('--accept-index');
    if (!/^(0|[1-9][0-9]*)$/.test(index) || !Number.isSafeInteger(Number(index)))
      throw new TypeError('--accept-index must be the displayed zero-based payment alternative.');
    Object.assign(result, { intentId: required('--intent'), acceptIndex: Number(index),
      offerSha256: required('--offer-sha'), destination: required('--out') });
  }
  return { action, input: result };
}
export async function main(args = process.argv.slice(2)) {
  if (!args.length || args.length === 1 && ['help', '--help'].includes(args[0])) {
    process.stdout.write(HELP); return;
  }
  if (['init', 'status', 'run', 'recover', 'export', 'deliver', 'accounting', 'finalize'].includes(args[0]))
    return (await import('../../sf88-operator-buyer-cli/dataset-cli.mjs')).main(args);
  if (!['offer', 'prepare'].includes(args[0])) throw new TypeError(HELP);
  const { action, input } = options(args);
  const report = action === 'offer' ? await reviewSdmxBuyer(input) : await prepareSdmxBuyer(input);
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { process.stderr.write(JSON.stringify({ error: error.code ?? 'SDMX_BUYER', message: error.message }) + '\n'); process.exitCode = 1; });

"""MIT. Source-bound customer catalogs for the Macrobond Web API Series Provider."""
from __future__ import annotations

from contextlib import contextmanager
from datetime import date
from decimal import Decimal, InvalidOperation
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import sqlite3
import stat
import sys
import tempfile
import threading
import uuid
import zipfile

SDMX = Path(__file__).resolve().parent.parent
if str(SDMX) not in sys.path:
    sys.path.insert(0, str(SDMX))
from sdmx_workspace import (
    Workspace, InputError, MAX_PACKET, MAX_METADATA, HEX, PROJECT_ID,
    digest, identity, text, page, now, json_bytes, load_json,
    private_write, regular, file_digest, sync_dir,
)
from sdmx_source import period_bounds

VERSION = "stellar-forge.macrobond-catalog.v1"
EDITION = "stellar-forge.macrobond-edition.v1"
PACKET = "stellar-forge.macrobond-catalog-packet.v1"
FREQUENCIES = {"A": "annual", "Q": "quarterly", "M": "monthly", "D": "daily",
               "B": "daily", "H": "semiannual", "S": "semiannual", "W": "weekly"}
_ENV_LOCK = threading.RLock()
NUMBER = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z")
SERIES_ID = re.compile(r"sdmx_[0-9a-f]{32}\Z")
PROVIDER_METHODS = {"getcapabilities", "loadseries", "loadmeta",
                    "searchseries", "loadtree", "listseries"}


def wire_json(value):
    """Write finite Decimal values as JSON numbers, preserving their decimal value."""
    def encode(item):
        if isinstance(item, Decimal):
            if not item.is_finite():
                raise InputError("Provider values must be finite")
            return str(item)
        if item is None or isinstance(item, (str, bool, int)):
            return json.dumps(item, ensure_ascii=False, allow_nan=False)
        if isinstance(item, float):
            if not math.isfinite(item):
                raise InputError("Provider values must be finite")
            return json.dumps(item, allow_nan=False)
        if isinstance(item, (list, tuple)):
            return "[" + ",".join(encode(v) for v in item) + "]"
        if isinstance(item, dict) and all(isinstance(k, str) for k in item):
            return "{" + ",".join(encode(k) + ":" + encode(v) for k, v in item.items()) + "}"
        raise InputError("Unsupported provider JSON value")
    return (encode(value) + "\n").encode("utf-8")


def projected_number(row):
    if row.get("action") == "Delete":
        raise InputError("A deletion record needs a selected complete source edition before publication")
    value = row.get("value")
    if not row.get("value_present") or value is None or value == "":
        return None
    if not isinstance(value, str) or len(value) > 4096 or not NUMBER.fullmatch(value):
        raise InputError("The source value is outside the supported numeric representation")
    try:
        number = Decimal(value)
    except InvalidOperation as error:
        raise InputError("The original source value is not a decimal number") from error
    if not number.is_finite():
        raise InputError("The original source value is not a finite decimal number")
    converted = float(number)
    if not math.isfinite(converted) or (converted == 0 and number != 0):
        raise InputError("The source number exceeds the Macrobond client's numeric range")
    return number


def projected_date(row, frequency):
    start, end = period_bounds(row["time_period"], frequency)
    if not start or not end:
        raise InputError("The source period does not match its declared supported frequency")
    anchor = date.fromisoformat(start)
    if not 1600 <= anchor.year <= 2499 or not 1600 <= date.fromisoformat(end).year <= 2499:
        raise InputError("The Macrobond provider date range is 1600 through 2499")
    return start + "T00:00:00"


def series_identity(flow, key):
    return "sdmx_" + digest(json_bytes([flow, key]))[:32]


def row_page(rows, offset, limit):
    offset, limit = page(offset, limit)
    return {"rows": rows[offset:offset + limit], "total": len(rows),
            "offset": offset, "limit": limit}


def file_record(path):
    return {"bytes": path.stat().st_size, "sha256": file_digest(path, MAX_PACKET)}


def publish_file(source, output):
    output = Path(output).expanduser().absolute()
    output.parent.mkdir(parents=True, exist_ok=True)
    expected = file_record(source)
    if output.exists() or output.is_symlink():
        if file_record(output) != expected:
            raise InputError("The existing output belongs to a different retained catalog")
        return {"path": str(output), **expected}
    fd, name = tempfile.mkstemp(prefix=".macrobond-packet-", dir=output.parent)
    staged = Path(name)
    try:
        with os.fdopen(fd, "wb") as target, source.open("rb") as origin:
            shutil.copyfileobj(origin, target, 65536)
            target.flush()
            os.fsync(target.fileno())
        try:
            os.link(staged, output)
        except FileExistsError:
            if file_record(output) != expected:
                raise InputError("The existing output belongs to a different retained catalog")
        sync_dir(output.parent)
    finally:
        staged.unlink(missing_ok=True)
    return {"path": str(output), **expected}


class Catalog:
    def __init__(self, root, create=False):
        root = Path(root).expanduser().absolute()
        if root.is_symlink():
            raise InputError("Use a real private catalog directory")
        if create:
            root.mkdir(mode=0o700, parents=True, exist_ok=False)
            private_write(root / "catalog.json", json_bytes({"schema": VERSION}))
        self.root = root.resolve(strict=True)
        regular(self.root / "catalog.json", 8192)
        if load_json((self.root / "catalog.json").read_bytes()) != {"schema": VERSION}:
            raise InputError("Unsupported Macrobond catalog schema")
        info = self.root.stat()
        if os.name == "posix" and (info.st_uid != os.getuid() or info.st_mode & 0o077):
            raise InputError("Use an operator-owned private catalog directory, mode 0700")
        self.source = Workspace(self.root / "source-workspace", create=create)
        self.mutex = self.source.mutex
        self.db = self.source.db
        try:
            with self.db:
                self.db.executescript("""
                    CREATE TABLE IF NOT EXISTS macrobond_info(id INTEGER PRIMARY KEY,body TEXT NOT NULL);
                    CREATE TABLE IF NOT EXISTS macrobond_editions(
                        id TEXT PRIMARY KEY,operation_id TEXT NOT NULL UNIQUE,
                        request_sha256 TEXT NOT NULL,request TEXT NOT NULL,body TEXT NOT NULL);
                    CREATE TABLE IF NOT EXISTS macrobond_current(
                        id INTEGER PRIMARY KEY,revision INTEGER NOT NULL,current TEXT);
                    CREATE TABLE IF NOT EXISTS macrobond_publications(revision INTEGER PRIMARY KEY,body TEXT NOT NULL);
                """)
                self.db.execute("INSERT OR IGNORE INTO macrobond_info VALUES(1,?)",
                    (json_bytes({"schema": VERSION, "id": uuid.uuid4().hex, "created_at": now()}).decode(),))
                self.db.execute("INSERT OR IGNORE INTO macrobond_current VALUES(1,0,NULL)")
            self._closed = False
        except Exception:
            self.source.close()
            raise

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def close(self):
        if not getattr(self, "_closed", True):
            self._closed = True
            self.source.close()

    def scratch(self):
        return self.source.scratch()

    @contextmanager
    def _native_environment(self):
        # The original child keeps a private temporary volume for its full lifetime.
        names = ("TMPDIR", "TEMP", "TMP", "SQLITE_TMPDIR")
        with _ENV_LOCK:
            prior = {name: os.environ.get(name) for name in names}
            previous_tempdir = tempfile.tempdir
            try:
                for name in names:
                    os.environ[name] = str(self.source.root / "tmp")
                tempfile.tempdir = str(self.source.root / "tmp")
                yield
            finally:
                tempfile.tempdir = previous_tempdir
                for name, value in prior.items():
                    if value is None:
                        os.environ.pop(name, None)
                    else:
                        os.environ[name] = value

    def state(self):
        with self.mutex:
            info = load_json(self.db.execute("SELECT body FROM macrobond_info WHERE id=1").fetchone()[0])
            current = self.db.execute("SELECT revision,current FROM macrobond_current WHERE id=1").fetchone()
            editions = [load_json(row[0])["edition"] for row in
                        self.db.execute("SELECT body FROM macrobond_editions ORDER BY rowid DESC")]
            history = [load_json(row[0]) for row in
                       self.db.execute("SELECT body FROM macrobond_publications ORDER BY revision")]
            return {"schema": VERSION, "workspace": {**info, "path": str(self.root)},
                    "source_state": self.source.state(), "editions": editions,
                    "current": current["current"], "revision": current["revision"],
                    "publications": history}

    def import_packet(self, path):
        with self.mutex, self._native_environment():
            return self.source.import_packet(path)

    def _request(self, body):
        if not isinstance(body, dict) or set(body) - {"operation_id", "title", "notes", "members"}:
            raise InputError("Use operation_id, title, notes and the selected source members")
        operation = text(body.get("operation_id"), "Operation identity", 200)
        title = text(body.get("title"), "Catalog edition title", 240)
        notes = text(body.get("notes", ""), "Analyst notes", 32000, empty=True)
        members = body.get("members")
        if not isinstance(members, list) or not 1 <= len(members) <= 1000:
            raise InputError("Select from 1 to 1000 retained source projects")
        selected, seen = [], set()
        for item in members:
            if not isinstance(item, dict) or set(item) - {"project_id", "revision", "series_keys"}:
                raise InputError("Each member needs its original project, revision and series selection")
            ident = identity(item.get("project_id"), PROJECT_ID)
            revision = item.get("revision")
            if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
                raise InputError("Select an explicit positive source project revision")
            if (ident, revision) in seen:
                raise InputError("Select a project revision once and combine its series selection")
            seen.add((ident, revision))
            keys = item.get("series_keys", [])
            if not isinstance(keys, list) or len(keys) > 100000:
                raise InputError("Series selection must be an array of original series keys")
            keys = sorted(set(text(k, "Original series key", 16384) for k in keys))
            selected.append({"project_id": ident, "revision": revision, "series_keys": keys})
        return {"operation_id": operation, "title": title, "notes": notes,
                "members": sorted(selected, key=lambda m: (m["project_id"], m["revision"]))}

    @contextmanager
    def _index(self, project, revision):
        view = self.source.project(project, revision)
        path = self.source._build_file(view["build"]["id"], "rows.sqlite")
        index = sqlite3.connect(path.as_uri() + "?mode=ro", uri=True)
        try:
            yield view, index
        finally:
            index.close()

    def _raw_rows(self, series, offset=None, limit=None):
        with self._index(series["source_project"], series["source_revision"]) as (_, index):
            sql = "SELECT body FROM rows WHERE series_key=? ORDER BY period,k"
            args = [series["series_key"]]
            if offset is not None:
                sql += " LIMIT ? OFFSET ?"
                args.extend([limit, offset])
            return [load_json(r[0]) for r in index.execute(sql, args)]

    @contextmanager
    def _row_stream(self, series):
        if series is None:
            yield iter(())
            return
        with self._index(series["source_project"], series["source_revision"]) as (_, index):
            cursor = index.execute(
                "SELECT body FROM rows WHERE series_key=? ORDER BY period,k", (series["series_key"],))
            yield (load_json(row[0]) for row in cursor)

    def _inspect(self, view, index, key):
        rows = index.execute("SELECT body FROM rows WHERE series_key=? ORDER BY period,k", (key,))
        first, count, first_date, last_date, has_weekend = None, 0, None, None, False
        units, multipliers, decimals, issues = set(), set(), set(), []
        lossy, sample, previous = 0, [], None
        frequencies = set()
        def issue(field, message, severity="error"):
            candidate = {"series_key": key, "field": field, "message": message, "severity": severity}
            if candidate not in issues:
                issues.append(candidate)
        for saved in rows:
            row = load_json(saved[0])
            first = first or row
            count += 1
            frequency = row["dimensions"].get("FREQ", "")
            frequencies.add(frequency)
            attrs = row["attributes"]
            units.add(attrs.get("UNIT", ""))
            multipliers.add(attrs.get("UNIT_MULT", ""))
            decimals.add(attrs.get("DECIMALS", ""))
            stamp, number = None, None
            try:
                if frequency not in FREQUENCIES:
                    raise InputError("The retained source frequency has no supported Macrobond calendar")
                stamp = projected_date(row, frequency)
                if previous is not None and stamp <= previous:
                    raise InputError("Source observations must have unique increasing calendar anchors")
                previous = stamp
                first_date = first_date or stamp
                last_date = stamp
                has_weekend = has_weekend or date.fromisoformat(stamp[:10]).weekday() >= 5
            except InputError as error:
                issue("time_period", str(error))
            try:
                number = projected_number(row)
                if number is not None and Decimal(str(float(number))) != number:
                    lossy += 1
            except InputError as error:
                issue("value", str(error))
            if len(sample) < 3:
                sample.append({"time_period": row["time_period"], "value": row["value"],
                               "value_present": row["value_present"], "value_kind": row["value_kind"],
                               "date": stamp, "wire_number": str(number) if number is not None else None,
                               "consumer_number": repr(float(number)) if number is not None else None})
        if first is None:
            raise InputError("A selected series has no retained observations")
        frequency = first["dimensions"].get("FREQ", "")
        if len(frequencies) != 1:
            issue("frequency", "A provider series must retain one source frequency")
        if len(units) != 1 or len(multipliers) != 1:
            issue("unit", "The selected series changes unit or unit multiplier across observations")
        if lossy:
            issue("value", f"{lossy} original values have more decimal precision than the client's binary64 round trip",
                  "warning")
        flow, ident = first["flow"], series_identity(first["flow"], key)
        project, build = view["project"], view["build"]
        unit, multiplier = next(iter(units), ""), next(iter(multipliers), "")
        denom = first["dimensions"].get("CURRENCY_DENOM", "")
        display_unit = unit + ("/" + denom if unit and denom else "")
        if multiplier not in {"", "0"}:
            display_unit += " (source multiplier 10^" + multiplier + ")"
        provenance = {
            "provider": "Stellar Forge retained SDMX catalog",
            "source_flow": flow, "series_key": key, "dimensions": first["dimensions"],
            "source_project": project["id"], "source_revision": project["revision"],
            "native_snapshot": build["snapshot"], "source_metadata_sha256": build["metadata"]["sha256"],
            "original_sources": [{"sha256": s["sha256"], "origin": s.get("origin", ""),
                                  "label": s.get("label", ""), "coverage": s.get("coverage", {})}
                                 for s in view["sources"]],
            "unit": unit, "unit_multiplier": multiplier, "declared_decimals": sorted(decimals),
            "values": "Original decimal values; no rescaling or rounding by SDMX DECIMALS.",
            "calendar": "Explicit source period anchors; the client may insert missing calendar periods.",
            "history": "Customer catalog publications; original source editions remain attached.",
        }
        metadata = {"PrimName": ident, "Description": flow + " / " + key,
                    "Frequency": FREQUENCIES.get(frequency, ""), "StartDate": first_date,
                    "EndDate": last_date,
                    "IHInfo": json.dumps(provenance, ensure_ascii=False, sort_keys=True, indent=2)}
        if display_unit:
            metadata["DisplayUnit"] = display_unit
        if frequency in {"D", "B"} and first_date:
            metadata["DayMask"] = 127 if has_weekend else 62
        return {
            "id": ident, "series_key": key, "flow": flow, "metaData": metadata,
            "frequency": FREQUENCIES.get(frequency, ""), "source_frequency": frequency,
            "unit": unit, "unit_multiplier": multiplier,
            "start_date": metadata["StartDate"], "end_date": metadata["EndDate"],
            "observation_count": count, "source_project": project["id"],
            "source_revision": project["revision"], "source_snapshot": build["snapshot"],
            "source_build": build["id"], "dimensions": first["dimensions"],
            "numeric_preview": sample, "lossy_consumer_values": lossy,
        }, issues

    def preview(self, body):
        request = self._request(body)
        with self.mutex:
            series, projects, issues, seen = [], [], [], set()
            for member in request["members"]:
                with self._index(member["project_id"], member["revision"]) as (view, index):
                    available = [r[0] for r in index.execute("SELECT DISTINCT series_key FROM rows ORDER BY series_key")]
                    selected = member["series_keys"] or available
                    missing = set(selected) - set(available)
                    if missing:
                        raise InputError("Selected series are absent from this source revision: " + ", ".join(sorted(missing)[:5]))
                    projects.append({"project": view["project"],
                        "build": {k: view["build"][k] for k in ("id", "snapshot", "row_count", "series_count")},
                        "sources": view["sources"]})
                    for key in selected:
                        item, found = self._inspect(view, index, key)
                        if item["id"] in seen:
                            raise InputError("The catalog selects the same source series through multiple projects; select one original edition")
                        seen.add(item["id"])
                        series.append(item)
                        issues.extend(found)
            return {"request": request, "projects": projects, "series": sorted(series, key=lambda s: s["id"]),
                    "issues": issues, "row_count": sum(s["observation_count"] for s in series)}

    def _edition_record(self, preview, created_at):
        request, series = preview["request"], preview["series"]
        sources, files = [], {}
        for member in request["members"]:
            view = self.source.project(member["project_id"], member["revision"])
            build = self.source._portable_build(view["build"])
            sources.append({"project_id": member["project_id"], "revision": member["revision"],
                            "snapshot": build["snapshot"], "build_id": build["id"],
                            "semantic_sha256": build["semantic_sha256"],
                            "source_ids": sorted(s["id"] for s in view["sources"])})
            files[member["project_id"] + "/" + str(member["revision"])] = build["files"]
        ident = digest(json_bytes({"schema": EDITION, "request": request, "series": series,
                                   "sources": sources, "files": files}))
        edition = {"schema": EDITION, "id": ident, "title": request["title"],
                   "created_at": created_at, "operation_id": request["operation_id"],
                   "members": request["members"], "notes": request["notes"],
                   "series_count": len(series), "row_count": preview["row_count"],
                   "sources": sources, "files": files}
        return {"edition": edition, "series": series}

    def save_edition(self, body):
        request = self._request(body)
        request_sha = digest(json_bytes(request))
        with self.mutex:
            previous = self.db.execute("SELECT request_sha256,body FROM macrobond_editions WHERE operation_id=?",
                                       (request["operation_id"],)).fetchone()
            if previous:
                if previous["request_sha256"] != request_sha:
                    raise InputError("This operation identity already belongs to a different saved catalog request")
                result = load_json(previous["body"])
                self._check_sources(result)
                return result
            preview = self.preview(request)
            failures = [issue for issue in preview["issues"] if issue.get("severity") == "error"]
            if failures:
                raise InputError("Review the source compatibility issues before saving: " +
                                 "; ".join(issue["series_key"] + ": " + issue["message"] for issue in failures[:5]))
            result = self._edition_record(preview, now())
            with self.db:
                self.db.execute("INSERT INTO macrobond_editions VALUES(?,?,?,?,?)",
                    (result["edition"]["id"], request["operation_id"], request_sha,
                     json_bytes(request).decode(), json_bytes(result).decode()))
            return result

    def _check_sources(self, result):
        for source in result["edition"]["sources"]:
            view = self.source.project(source["project_id"], source["revision"])
            if view["build"]["id"] != source["build_id"] or view["build"]["snapshot"] != source["snapshot"]:
                raise InputError("The saved catalog source differs from its immutable native project")

    def edition(self, ident):
        identity(ident)
        with self.mutex:
            row = self.db.execute("SELECT body FROM macrobond_editions WHERE id=?", (ident,)).fetchone()
            if row is None:
                raise InputError("Unknown saved catalog edition")
            result = load_json(row["body"])
            self._check_sources(result)
            return result

    def series(self, ident, offset=0, limit=50, query=""):
        query = text(query, "Series query", 4096, empty=True).casefold()
        with self.mutex:
            rows = self.edition(ident)["series"]
            if query:
                rows = [s for s in rows if query in
                        (s["id"] + " " + s["series_key"] + " " + s["flow"] + " " +
                         s["metaData"]["Description"]).casefold()]
            return row_page(rows, offset, limit)

    def _selected_series(self, ident, series_id):
        if not isinstance(series_id, str) or not SERIES_ID.fullmatch(series_id):
            raise InputError("Use the complete retained provider series identity")
        item = next((s for s in self.edition(ident)["series"] if s["id"] == series_id), None)
        if item is None:
            raise InputError("Unknown series in this catalog edition")
        return item

    def observations(self, ident, series_id, offset=0, limit=50):
        offset, limit = page(offset, limit)
        with self.mutex:
            selected = self._selected_series(ident, series_id)
            rows = self._raw_rows(selected, offset, limit)
            return {"rows": [{**row, "date": projected_date(row, selected["source_frequency"])}
                             for row in rows],
                    "total": selected["observation_count"], "offset": offset, "limit": limit}

    def activate(self, ident, expected_revision, expected_current):
        if isinstance(expected_revision, bool) or not isinstance(expected_revision, int) or expected_revision < 0:
            raise InputError("Publication needs the current nonnegative revision")
        if expected_current is not None:
            identity(expected_current)
        with self.mutex:
            self.edition(ident)
            current = self.db.execute("SELECT revision,current FROM macrobond_current WHERE id=1").fetchone()
            if current["current"] == ident and current["revision"] == expected_revision + 1:
                prior = self.db.execute("SELECT body FROM macrobond_publications WHERE revision=?",
                                        (current["revision"],)).fetchone()
                if prior and load_json(prior["body"])["previous"] == expected_current:
                    return self.state()
            if current["revision"] != expected_revision or current["current"] != expected_current:
                raise InputError("The selected publication changed; refresh and compare the current saved edition")
            if current["current"] == ident:
                return self.state()
            event = {"revision": expected_revision + 1, "previous": expected_current,
                     "current": ident, "activated_at": now()}
            with self.db:
                self.db.execute("INSERT INTO macrobond_publications VALUES(?,?)",
                                (event["revision"], json_bytes(event).decode()))
                self.db.execute("UPDATE macrobond_current SET revision=?,current=? WHERE id=1",
                                (event["revision"], ident))
            return self.state()

    def compare(self, before_id, after_id):
        with self.mutex:
            before, after = self.edition(before_id), self.edition(after_id)
            old = {s["id"]: s for s in before["series"]}
            new = {s["id"]: s for s in after["series"]}
            total = {k: 0 for k in ("added", "removed", "changed", "unchanged")}
            series_counts = dict(total)
            rows = []
            for ident in sorted(set(old) | set(new)):
                a, b = old.get(ident), new.get(ident)
                counts = {k: 0 for k in total}
                with self._row_stream(a) as left, self._row_stream(b) as right:
                    av, bv = next(left, None), next(right, None)
                    while av is not None or bv is not None:
                        if av is None or (bv is not None and bv["time_period"] < av["time_period"]):
                            counts["added"] += 1
                            bv = next(right, None)
                        elif bv is None or av["time_period"] < bv["time_period"]:
                            counts["removed"] += 1
                            av = next(left, None)
                        else:
                            counts["unchanged" if av == bv else "changed"] += 1
                            av, bv = next(left, None), next(right, None)
                metadata_changed = bool(a and b and a["metaData"] != b["metaData"])
                source_changed = bool(a and b and
                    (a["source_project"], a["source_revision"], a["source_snapshot"]) !=
                    (b["source_project"], b["source_revision"], b["source_snapshot"]))
                kind = ("added" if a is None else "removed" if b is None else
                        "changed" if metadata_changed or source_changed or
                        any(counts[k] for k in ("added", "removed", "changed")) else "unchanged")
                series_counts[kind] += 1
                for key in total:
                    total[key] += counts[key]
                rows.append({"id": ident, "series_key": (b or a)["series_key"], "kind": kind,
                             "metadata_changed": metadata_changed, "source_changed": source_changed,
                             "counts": counts})
            return {"before": before_id, "after": after_id, "series_counts": series_counts,
                    "observation_counts": total, "rows": rows}

    def _provider_names(self, params):
        names = params.get("n", [])
        if isinstance(names, str):
            names = [names]
        if not isinstance(names, list) or not 1 <= len(names) <= 1000:
            raise InputError("Supply one or more repeated n series parameters, up to 1000")
        if any(not isinstance(n, str) or len(n) > 256 for n in names):
            raise InputError("Provider series names must be strings within 256 characters")
        return names

    def _browse_groups(self, series):
        flows = {}
        for item in series:
            flow_id = "f_" + digest(item["flow"].encode())[:24]
            group = flows.setdefault(flow_id, {"flow": item["flow"], "series": [], "frequencies": {}})
            group["series"].append(item)
            group["frequencies"].setdefault(item["source_frequency"], []).append(item)
        return flows

    def provider(self, command, params):
        if command not in PROVIDER_METHODS:
            raise InputError("Unsupported Macrobond provider method")
        if not isinstance(params, dict):
            raise InputError("Provider parameters must be a query object")
        if command == "getcapabilities":
            return {"browse": True, "search": True, "editSeries": False,
                    "allowMultipleSeriesPerRequest": True, "meta": True,
                    "revisions": False, "revisionsRelease": False, "revisionsCompleteHistory": False}
        with self.mutex:
            current = self.db.execute("SELECT current FROM macrobond_current WHERE id=1").fetchone()[0]
            selected = self.edition(current)["series"] if current else []
            by_id = {s["id"]: s for s in selected}
            if command in {"loadseries", "loadmeta"}:
                output = []
                for name in self._provider_names(params):
                    item = by_id.get(name)
                    if item is None:
                        output.append({"error": "Unknown series in the selected catalog publication: " + name})
                        continue
                    data = {"metaData": item["metaData"]}
                    if command == "loadseries":
                        data["values"], data["dates"] = [], []
                        with self._row_stream(item) as original:
                            for row in original:
                                data["values"].append(projected_number(row))
                                data["dates"].append(projected_date(row, item["source_frequency"]))
                    output.append({"data": data})
                return output
            if command == "searchseries":
                query = text(params.get("query", ""), "Search query", 4096, empty=True).casefold()
                return [s["metaData"] for s in selected if query in
                        (s["id"] + " " + s["series_key"] + " " + s["flow"] + " " +
                         s["metaData"]["Description"]).casefold()]
            reference = text(params.get("reference", ""), "Browse reference", 256, empty=True)
            groups = self._browse_groups(selected)
            if command == "loadtree":
                if not reference:
                    return [{"Description": value["flow"], "ChildrenReference": key}
                            for key, value in sorted(groups.items(), key=lambda pair: pair[1]["flow"])]
                if reference not in groups:
                    raise InputError("Unknown catalog tree reference")
                return [{"Description": FREQUENCIES[freq], "SeriesReference": reference + "." + freq}
                        for freq in sorted(groups[reference]["frequencies"])]
            if not reference:
                rows = selected
            else:
                flow, separator, frequency = reference.partition(".")
                if flow not in groups or (separator and frequency not in groups[flow]["frequencies"]):
                    raise InputError("Unknown catalog series reference")
                rows = groups[flow]["frequencies"][frequency] if separator else groups[flow]["series"]
            return {"groups": [{"name": "Selected catalog publication", "series": [
                {"description": s["metaData"]["Description"], "names": [s["id"]],
                 "entityMeta": [s["metaData"]]} for s in rows]}]}

    def export_packet(self, ident, output):
        with self.mutex, self.scratch() as temporary:
            selected = self.edition(ident)
            records = [{"request": load_json(row["request"]), "result": load_json(row["body"])}
                       for row in self.db.execute("SELECT request,body FROM macrobond_editions ORDER BY rowid")]
            state = self.state()
            projects = {}
            for record in records:
                for member in record["request"]["members"]:
                    projects[member["project_id"]] = max(
                        projects.get(member["project_id"], 0), member["revision"])
            packet = {"schema": PACKET,
                      "catalog": {k: state["workspace"][k] for k in ("schema", "id", "created_at")},
                      "selected_edition": ident,
                      "state": {"revision": state["revision"], "current": state["current"]},
                      "editions": records, "publications": state["publications"],
                      "projects": [], "files": {}}
            retained = {}
            for project_id, revision in sorted(projects.items()):
                name = "projects/" + project_id + ".sdmx.zip"
                path = temporary / (project_id + ".sdmx.zip")
                exported = self.source.export_packet(project_id, path, revision)
                retained[name] = path
                packet["files"][name] = {"bytes": exported["bytes"], "sha256": exported["sha256"]}
                packet["projects"].append({"project_id": project_id, "revision": revision, "path": name})
            manifest = json_bytes(packet)
            if len(manifest) > MAX_METADATA:
                raise InputError("The catalog manifest exceeds 32 MiB")
            archive = temporary / "catalog.zip"
            with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as z:
                def entry(name):
                    item = zipfile.ZipInfo(name, date_time=(2026, 1, 1, 0, 0, 0))
                    item.compress_type = zipfile.ZIP_DEFLATED
                    item.create_system = 3
                    item.external_attr = 0o100600 << 16
                    return item
                z.writestr(entry("macrobond-catalog.json"), manifest)
                for name, path in sorted(retained.items()):
                    with path.open("rb") as source, z.open(entry(name), "w") as target:
                        shutil.copyfileobj(source, target, 65536)
            os.chmod(archive, 0o600)
            return {**publish_file(archive, output), "edition": selected["edition"],
                    "edition_count": len(records), "publication_count": len(state["publications"]),
                    "source_project_count": len(projects)}

    def _preflight_catalog(self, manifest):
        if not isinstance(manifest, dict) or manifest.get("schema") != PACKET:
            raise InputError("Unsupported complete Macrobond catalog packet")
        records = manifest.get("editions")
        if not isinstance(records, list) or not records or len(records) > 100000:
            raise InputError("The packet must contain its saved catalog editions")
        ids, operations, projects = set(), set(), {}
        for record in records:
            if not isinstance(record, dict) or set(record) != {"request", "result"}:
                raise InputError("A catalog edition needs its original request and result")
            request = self._request(record["request"])
            if request != record["request"]:
                raise InputError("The catalog contains an unnormalized saved request")
            result = record["result"]
            if not isinstance(result, dict) or set(result) != {"edition", "series"}:
                raise InputError("The catalog edition result is incomplete")
            edition = result["edition"]
            if not isinstance(edition, dict) or not isinstance(result["series"], list):
                raise InputError("The catalog edition metadata or series list is invalid")
            ident = identity(edition.get("id"))
            if edition.get("schema") != EDITION or ident in ids or request["operation_id"] in operations:
                raise InputError("The catalog contains repeated or unsupported edition identities")
            ids.add(ident)
            operations.add(request["operation_id"])
            text(edition.get("created_at"), "Retained edition timestamp", 80)
            for member in request["members"]:
                projects[member["project_id"]] = max(projects.get(member["project_id"], 0), member["revision"])
            previous = self.db.execute("SELECT request,body FROM macrobond_editions WHERE operation_id=?",
                                       (request["operation_id"],)).fetchone()
            if previous and (load_json(previous["request"]) != request or load_json(previous["body"]) != result):
                raise InputError("This catalog retains a different original request or edition under that operation")
        if manifest.get("selected_edition") not in ids:
            raise InputError("The packet's selected edition is absent")
        state, history = manifest.get("state"), manifest.get("publications")
        if not isinstance(state, dict) or set(state) != {"revision", "current"} or not isinstance(history, list):
            raise InputError("The original publication state and history are required")
        if isinstance(state["revision"], bool) or state["revision"] != len(history):
            raise InputError("The publication revision differs from its complete history")
        previous = None
        for revision, event in enumerate(history, 1):
            if not isinstance(event, dict) or set(event) != {"revision", "previous", "current", "activated_at"}:
                raise InputError("Unsupported retained publication event")
            if event["revision"] != revision or event["previous"] != previous or event["current"] not in ids:
                raise InputError("The packet publication history is not a complete ordered sequence")
            text(event["activated_at"], "Publication timestamp", 80)
            previous = event["current"]
        if state["current"] != previous:
            raise InputError("The selected publication differs from the original history")
        catalog = manifest.get("catalog")
        if not isinstance(catalog, dict) or set(catalog) != {"schema", "id", "created_at"} or catalog["schema"] != VERSION:
            raise InputError("The original catalog identity is required")
        identity(catalog["id"], PROJECT_ID)
        text(catalog["created_at"], "Original catalog timestamp", 80)
        local = self.state()
        if local["editions"]:
            if catalog["id"] != local["workspace"]["id"] or catalog["created_at"] != local["workspace"]["created_at"]:
                raise InputError("Open a new receiving catalog for another catalog's complete history")
            if not {e["id"] for e in local["editions"]}.issubset(ids):
                raise InputError("This catalog has later saved editions; receive the older packet in a new workspace")
            if history[:len(local["publications"])] != local["publications"]:
                raise InputError("This catalog has a different publication continuation; receive the packet separately")
        declared_projects = manifest.get("projects")
        if not isinstance(declared_projects, list) or len(declared_projects) != len(projects):
            raise InputError("The packet must contain every selected original project history")
        expected_paths = set()
        for project in declared_projects:
            if not isinstance(project, dict) or set(project) != {"project_id", "revision", "path"}:
                raise InputError("Unsupported original project packet reference")
            pid = identity(project["project_id"], PROJECT_ID)
            expected_path = "projects/" + pid + ".sdmx.zip"
            if project["path"] != expected_path or projects.get(pid) != project["revision"] or expected_path in expected_paths:
                raise InputError("The project packet reference differs from the selected edition history")
            expected_paths.add(expected_path)
        if not isinstance(manifest.get("files"), dict) or set(manifest["files"]) != expected_paths:
            raise InputError("The catalog packet file set differs from its complete source history")
        return records

    def import_catalog(self, path):
        path = Path(path).expanduser().absolute()
        if path.is_symlink() or not path.is_file() or path.stat().st_size > MAX_PACKET:
            raise InputError("Select a regular complete catalog packet within 1 GiB")
        try:
            archive = zipfile.ZipFile(path)
        except (OSError, zipfile.BadZipFile) as error:
            raise InputError("Select a complete Macrobond catalog ZIP packet") from error
        with self.mutex, archive as z, self.scratch() as temporary:
            members = z.infolist()
            if len(members) > 4096 or len({item.filename for item in members}) != len(members):
                raise InputError("The catalog packet has repeated or excessive members")
            if "macrobond-catalog.json" not in z.namelist():
                raise InputError("The complete catalog manifest is missing")
            if z.getinfo("macrobond-catalog.json").file_size > MAX_METADATA:
                raise InputError("The catalog manifest exceeds 32 MiB")
            manifest = load_json(z.read("macrobond-catalog.json"))
            records = self._preflight_catalog(manifest)
            if set(z.namelist()) != set(manifest["files"]) | {"macrobond-catalog.json"}:
                raise InputError("The packet archive differs from its declared source files")
            total = 0
            for item in members:
                if (item.is_dir() or item.filename.startswith("/") or "\\" in item.filename
                        or any(part in {"", ".", ".."} for part in item.filename.split("/"))
                        or stat.S_IFMT(item.external_attr >> 16) not in {0, stat.S_IFREG}
                        or item.flag_bits & 1):
                    raise InputError("Catalog packet members must be unencrypted regular files")
                total += item.file_size
                if total > MAX_PACKET or item.file_size > MAX_PACKET:
                    raise InputError("The expanded catalog packet exceeds 1 GiB")
                if item.filename == "macrobond-catalog.json":
                    continue
                expected = manifest["files"][item.filename]
                if (not isinstance(expected, dict) or item.file_size != expected.get("bytes")
                        or not isinstance(expected.get("sha256"), str) or not HEX.fullmatch(expected["sha256"])):
                    raise InputError("The original source packet size or identity differs from its declaration")
                h = hashlib.sha256()
                with z.open(item) as source:
                    while block := source.read(65536):
                        h.update(block)
                if h.hexdigest() != expected["sha256"]:
                    raise InputError("The original source packet bytes differ from their declared identity")
            received, source_sizes = [], {}
            # Inspect all nested original manifests before invoking the maintained
            # recoverable source importer. Count shared raw sources once.
            for project in manifest["projects"]:
                target = temporary / (project["project_id"] + ".sdmx.zip")
                private_write(target, b"")
                with z.open(project["path"]) as source, target.open("wb") as destination:
                    shutil.copyfileobj(source, destination, 65536)
                    destination.flush()
                    os.fsync(destination.fileno())
                if file_record(target) != manifest["files"][project["path"]]:
                    raise InputError("The original project packet changed during receiving")
                with zipfile.ZipFile(target) as nested:
                    info = nested.getinfo("sdmx-packet.json")
                    if info.file_size > MAX_METADATA:
                        raise InputError("A source project manifest exceeds 32 MiB")
                    original = load_json(nested.read("sdmx-packet.json"))
                    if original.get("project_id") != project["project_id"] or original.get("revision") != project["revision"]:
                        raise InputError("The nested original project differs from the catalog reference")
                    for metadata in original.get("files", {}).values():
                        sid, size = metadata.get("sha256"), metadata.get("bytes")
                        if not isinstance(sid, str) or not HEX.fullmatch(sid) or isinstance(size, bool) or not isinstance(size, int) or size < 0:
                            raise InputError("Invalid original source size or identity")
                        if sid in source_sizes and source_sizes[sid] != size:
                            raise InputError("The same source has conflicting retained sizes")
                        source_sizes[sid] = size
                    if sum(source_sizes.values()) > MAX_PACKET:
                        raise InputError("The complete catalog retains more than 1 GiB of original source bytes")
                received.append((project, target))
            for project, target in received:
                imported = self.import_packet(target)
                if imported["project"]["id"] != project["project_id"] or imported["project"]["revision"] != project["revision"]:
                    raise InputError("The original source importer returned a different project edition")
            prepared = []
            for record in records:
                preview = self.preview(record["request"])
                if any(issue["severity"] == "error" for issue in preview["issues"]):
                    raise InputError("A retained catalog edition has incompatible original source observations")
                rebuilt = self._edition_record(preview, record["result"]["edition"]["created_at"])
                if rebuilt != record["result"]:
                    raise InputError("The received catalog projection differs from its original source-bound edition")
                prepared.append((record["request"], rebuilt))
            # Source imports are recoverable native operations. Publish the catalog
            # and its complete history together only after every edition matches.
            with self.db:
                for request, result in prepared:
                    self.db.execute("INSERT OR IGNORE INTO macrobond_editions VALUES(?,?,?,?,?)",
                        (result["edition"]["id"], request["operation_id"], digest(json_bytes(request)),
                         json_bytes(request).decode(), json_bytes(result).decode()))
                self.db.execute("UPDATE macrobond_info SET body=? WHERE id=1",
                                (json_bytes(manifest["catalog"]).decode(),))
                for event in manifest["publications"]:
                    self.db.execute("INSERT OR IGNORE INTO macrobond_publications VALUES(?,?)",
                                    (event["revision"], json_bytes(event).decode()))
                self.db.execute("UPDATE macrobond_current SET revision=?,current=? WHERE id=1",
                                (manifest["state"]["revision"], manifest["state"]["current"]))
            return self.state()

