class LimitedReader:
    def __init__(self, source, length):
        self.source, self.remaining = source, length

    def read(self, size=-1):
        if not self.remaining:
            return b""
        block = self.source.read(min(self.remaining, size if size >= 0 else self.remaining))
        if not block:
            raise InputError("Upload ended before its declared content length")
        self.remaining -= len(block)
        return block


class OperatorServer(ThreadingHTTPServer):
    daemon_threads = False
    block_on_close = True

    def __init__(self, catalog: Catalog, port=0, *, provider_username=None, provider_password=None):
        self.catalog, self.token = catalog, secrets.token_urlsafe(32)
        self.provider_username = provider_username
        self._provider_credentials = None
        if provider_username is not None or provider_password is not None:
            if (not isinstance(provider_username, str) or not provider_username or ":" in provider_username
                    or not isinstance(provider_password, str) or not provider_password):
                raise InputError("Provide a nonempty provider username without a colon and a nonempty password")
            self._provider_credentials = (provider_username + ":" + provider_password).encode("utf-8")
        self.slots = threading.BoundedSemaphore(8)
        super().__init__(("127.0.0.1", port), Handler)
        self.origin = f"http://127.0.0.1:{self.server_port}"
        self.url = self.origin + "/#" + self.token
        self.provider_url = self.origin + "/"

    def process_request(self, request, client_address):
        if not self.slots.acquire(blocking=False):
            self.shutdown_request(request)
            return
        try:
            super().process_request(request, client_address)
        except Exception:
            self.slots.release()
            raise

    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            self.slots.release()

    def connection_info(self):
        return {"provider_url": self.provider_url, "authentication": "Basic",
                "enabled": self._provider_credentials is not None,
                "username": self.provider_username}


class Handler(BaseHTTPRequestHandler):
    server_version = "SF30-Macrobond"
    protocol_version = "HTTP/1.0"

    def setup(self):
        super().setup()
        self.connection.settimeout(60)

    def log_message(self, *_):
        pass

    def _gate(self, private=True):
        target = urlsplit(self.path)
        if len(self.headers.get_all("Host", [])) != 1 or len(self.headers.get_all("Origin", [])) > 1:
            raise PermissionError("Repeated local origin or host headers are not accepted")
        if target.scheme or target.netloc or self.headers.get("Host") != urlsplit(self.server.origin).netloc:
            raise PermissionError("Invalid local host")
        if self.headers.get("Origin") not in {None, self.server.origin}:
            raise PermissionError("Cross-origin requests are not accepted")
        if private:
            supplied = self.headers.get("Authorization", "")
            if (len(self.headers.get_all("Authorization", [])) != 1
                    or not secrets.compare_digest(supplied.encode(), ("Bearer " + self.server.token).encode())):
                raise PermissionError("Open this process's private console link")
        return target

    def _headers(self, status, media, length, filename=None, *, provider=False, authenticate=False):
        self.send_response(status)
        self.send_header("Content-Type", media)
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "no-cache, private" if provider else "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Resource-Policy", "same-origin")
        self.send_header("Content-Security-Policy", "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
        if authenticate:
            self.send_header("WWW-Authenticate", 'Basic realm="Macrobond series provider", charset="UTF-8"')
        if filename:
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
        self.end_headers()

    def _json(self, value, status=200, *, provider=False, authenticate=False):
        data = wire_json(value) if provider else json_bytes(value)
        self._headers(status, "application/json; charset=utf-8", len(data),
                      provider=provider, authenticate=authenticate)
        self.wfile.write(data)

    def _provider_gate(self):
        credentials = self.server._provider_credentials
        if credentials is None:
            self._json({"error": "Provider credentials are not configured"}, 503, provider=True)
            return False
        supplied = self.headers.get("Authorization", "")
        scheme, _, encoded = supplied.partition(" ")
        try:
            decoded = base64.b64decode(encoded, validate=True)
        except (ValueError, binascii.Error):
            decoded = b""
        if (len(self.headers.get_all("Authorization", [])) != 1 or scheme.lower() != "basic"
                or not secrets.compare_digest(decoded, credentials)):
            self._json({"error": "Provider authentication is required"}, 401, provider=True, authenticate=True)
            return False
        return True

    def _body(self, maximum=131072):
        raw = self.headers.get("Content-Length", "")
        if self.headers.get("Transfer-Encoding") or len(self.headers.get_all("Content-Length", [])) != 1 or not raw.isdecimal():
            raise InputError("A single Content-Length is required")
        length = int(raw)
        if length > maximum:
            raise InputError("Request exceeds its size limit")
        return LimitedReader(self.rfile, length)

    def _query(self, target, provider=False):
        values = parse_qs(target.query, keep_blank_values=True)
        if any(len(items) != 1 for key, items in values.items() if not (provider and key == "n")):
            raise InputError("Repeated query parameters are accepted only for provider series names")
        return {key: items if provider and key == "n" else items[0] for key, items in values.items()}

    def _integer(self, query, key, default, minimum=0, maximum=100000000):
        raw = query.get(key, str(default))
        if not raw.isdecimal():
            raise InputError(f"{key} must be a nonnegative integer")
        value = int(raw)
        if not minimum <= value <= maximum:
            raise InputError(f"{key} is outside its supported range")
        return value

    def _state(self):
        return {**self.server.catalog.state(), "connection": self.server.connection_info()}

    def _download(self, path, filename):
        with path.open("rb") as stream:
            self._headers(200, "application/zip", path.stat().st_size, filename)
            shutil.copyfileobj(stream, self.wfile, 65536)

    def _run(self, callback):
        try:
            callback()
        except PermissionError as error:
            self._json({"error": str(error)}, 403)
        except (InputError, ValueError, KeyError, zipfile.BadZipFile) as error:
            status = getattr(error, "status", 400)
            self._json({"error": str(error)}, status if status in {400, 409, 413, 422} else 400)
        except FileNotFoundError:
            self._json({"error": "Retained project, edition or series was not found"}, 404)
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            pass
        except Exception:
            self._json({"error": "The local operation failed; the retained catalog remains available"}, 500)

    def do_GET(self):
        self._run(self._get)

    def _get(self):
        target = self._gate(private=False)
        assets = {"/": ("index.html", "text/html; charset=utf-8"),
                  "/app.js": ("app.js", "text/javascript; charset=utf-8"),
                  "/style.css": ("style.css", "text/css; charset=utf-8")}
        if target.path in assets:
            name, media = assets[target.path]
            data = (HERE / "public" / name).read_bytes()
            self._headers(200, media, len(data))
            self.wfile.write(data)
            return
        parts = target.path.strip("/").split("/")
        catalog = self.server.catalog
        command = parts[0] if len(parts) == 1 and parts[0] in PROVIDER_COMMANDS else (
            parts[1] if len(parts) == 2 and parts[0] == "provider" else None)
        if command is not None:
            if self._provider_gate():
                self._json(catalog.provider(command, self._query(target, provider=True)), provider=True)
            return
        self._gate()
        if target.path == "/api/state":
            self._json(self._state())
            return
        if len(parts) == 3 and parts[:2] == ["api", "provider"]:
            self._json(catalog.provider(parts[2], self._query(target, provider=True)), provider=True)
            return
        query = self._query(target)
        if target.path == "/api/connection.xml":
            data = definition_xml(query.get("host", self.server.provider_url))
            self._headers(200, "application/xml; charset=utf-8", len(data), "macrobond-provider.xml")
            self.wfile.write(data)
            return
        if len(parts) in {3, 4} and parts[:2] == ["api", "editions"]:
            ident = parts[2]
            if len(parts) == 3:
                self._json(catalog.edition(ident))
            elif parts[3] == "series":
                self._json(catalog.series(ident, self._integer(query, "offset", 0),
                    self._integer(query, "limit", 50, 1, 200), query.get("query", "")))
            elif parts[3] == "observations":
                self._json(catalog.observations(ident, query.get("series_id", ""),
                    self._integer(query, "offset", 0), self._integer(query, "limit", 50, 1, 200)))
            elif parts[3] == "packet":
                with catalog.mutex, catalog.scratch() as temporary:
                    path = temporary / "macrobond-catalog.zip"
                    catalog.export_packet(ident, path)
                    self._download(path, "macrobond-catalog.zip")
            else:
                self._json({"error": "Unknown local route"}, 404)
            return
        self._json({"error": "Unknown local route"}, 404)

    def do_POST(self):
        self._run(self._post)

    def _post(self):
        target = self._gate()
        catalog = self.server.catalog
        if target.path in {"/api/projects/import", "/api/catalog/import"}:
            with catalog.mutex, catalog.scratch() as temporary:
                path = temporary / "input.zip"
                with path.open("xb") as stream:
                    path.chmod(0o600)
                    shutil.copyfileobj(self._body(MAX_PACKET), stream, 65536)
                if target.path == "/api/projects/import":
                    result = catalog.import_packet(path)
                else:
                    catalog.import_catalog(path)
                    result = self._state()
            self._json(result, 201)
            return
        body = load_json(self._body().read())
        if not isinstance(body, dict):
            raise InputError("Expected a JSON object")
        if target.path == "/api/preview":
            self._json(catalog.preview(body))
        elif target.path == "/api/editions":
            self._json(catalog.save_edition(body), 201)
        elif target.path == "/api/editions/compare":
            self._json(catalog.compare(body["before"], body["after"]))
        else:
            parts = target.path.strip("/").split("/")
            if len(parts) == 4 and parts[:2] == ["api", "editions"] and parts[3] == "activate":
                catalog.activate(parts[2], body["expected_revision"], body.get("expected_current"))
                self._json(self._state())
            else:
                self._json({"error": "Unknown local route"}, 404)

// MIT. Retained SDMX editions through the ORIGINAL SF30 seller and version store.
import { constants } from 'node:fs';
import { open, mkdir, link, rm, lstat } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';
import { loadDatasetConfig } from '../dataset-handler.mjs';
import { buildDatasetSellerConfig } from '../dataset-cli.mjs';
import { DATASET_SNAPSHOT_PARAMETER, openDatasetVersions } from '../dataset-refresh/versions.mjs';
import { startVersionedDatasetSeller, datasetControl } from '../dataset-refresh/service.mjs';

export const SDMX_MERCHANT_RELEASE_SCHEMA = 'stellar-forge.sdmx-merchant-release.v1';
const BINDING_SCHEMA = 'stellar-forge.sdmx-seller-binding.v1';
const HASH = /^[a-f0-9]{64}$/;
const DATA_FILES = ['data.csv', 'dataset.json', 'sdmx-lineage.json', 'seller.json'];
const limits = { 'data.csv': 256 * 1024 * 1024, 'dataset.json': 65536,
  'sdmx-lineage.json': 8 * 1024 * 1024, 'seller.json': 1048576 };
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fault = (code, message, status = 400) => Object.assign(new Error(message), { code, status });
const encode = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const digest = value => createHash('sha256').update(value).digest('hex');
const canonical = value => JSON.stringify(value, (_, item) => object(item)
  ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
const same = (a, b) => canonical(a) === canonical(b);
const count = (value, label, minimum = 1, maximum = Number.MAX_SAFE_INTEGER) => {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum)
    throw new TypeError(label + ' must be an integer from ' + minimum + ' to ' + maximum);
  return value;
};
const identity = info => [info.dev, info.ino, info.size, info.mtimeNs, info.ctimeNs].join(':');
async function exists(path) {
  try { await lstat(path); return true; } catch (error) { if (error.code === 'ENOENT') return false; throw error; }
}
async function privateDirectory(path) {
  await mkdir(path, { recursive: true, mode: 0o700 });
  const info = await lstat(path);
  if (!info.isDirectory() || info.isSymbolicLink())
    throw fault('SDMX_DIRECTORY_REQUIRED', 'Select an original regular private directory.');
}
async function syncDirectory(path) {
  const handle = await open(path, constants.O_RDONLY);
  try { await handle.sync(); } finally { await handle.close(); }
}
async function inspectFile(path, maximum, retain = false) {
  const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const before = await handle.stat({ bigint: true });
    if (!before.isFile() || before.size > BigInt(maximum))
      throw fault('SDMX_FILE_LIMIT', 'An SDMX release file is not regular or exceeds its native limit.');
    const hash = createHash('sha256'), chunks = []; let bytes = 0;
    for await (const chunk of handle.createReadStream({ autoClose: false })) {
      bytes += chunk.length;
      if (bytes > maximum) throw fault('SDMX_FILE_LIMIT', 'An SDMX release file exceeds its native limit.');
      hash.update(chunk); if (retain) chunks.push(chunk);
    }
    if (identity(before) !== identity(await handle.stat({ bigint: true })))
      throw fault('SDMX_SOURCE_CHANGED', 'The selected immutable SDMX file changed while being read.', 409);
    return { bytes, sha256: hash.digest('hex'), ...(retain ? { data: Buffer.concat(chunks) } : {}) };
  } finally { await handle.close(); }
}
async function jsonFile(path, maximum) {
  const file = await inspectFile(path, maximum, true);
  let value;
  try { value = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(file.data)); }
  catch { throw fault('SDMX_JSON_INVALID', 'The selected SDMX JSON file is not valid UTF-8 JSON.'); }
  return { value, file };
}
function fileIdentity(value, maximum) {
  if (!object(value) || !HASH.test(value.sha256 ?? '') || !Number.isSafeInteger(value.bytes) ||
      value.bytes < 1 || value.bytes > maximum)
    throw fault('SDMX_LINEAGE_INVALID', 'The SDMX lineage must retain exact native file lengths and SHA256 values.');
  return { bytes: value.bytes, sha256: value.sha256 };
}
function projectIdentity(value) {
  if (!object(value) || typeof value.id !== 'string' || !value.id || value.id.length > 256 ||
      /[\x00-\x1f\x7f]/.test(value.id) || !Number.isSafeInteger(value.revision) || value.revision < 1 ||
      typeof value.title !== 'string' || !value.title)
    throw fault('SDMX_LINEAGE_INVALID', 'The SDMX lineage must identify the saved project revision.');
  return { id: value.id, revision: value.revision, title: value.title };
}
function releaseIdentity(value) {
  return digest(canonical({ schema: value.schema, project: value.project, snapshot: value.snapshot,
    resource: value.resource, files: value.files }));
}
async function readProjection(directory) {
  const root = resolve(directory);
  const lineageFile = await jsonFile(join(root, 'sdmx-lineage.json'), limits['sdmx-lineage.json']);
  const lineage = lineageFile.value;
  if (!object(lineage) || lineage.schema !== 'stellar-forge.sdmx-lineage.v1' ||
      !HASH.test(lineage.snapshot ?? '') || !object(lineage.files) || !Array.isArray(lineage.sources))
    throw fault('SDMX_LINEAGE_INVALID', 'Export an original saved SDMX dataset before preparing a merchant.');
  const project = projectIdentity(lineage.project);
  const expected = Object.fromEntries(['data.csv', 'dataset.json'].map(name =>
    [name, fileIdentity(lineage.files[name], limits[name])]));
  for (const name of Object.keys(expected)) {
    const actual = await inspectFile(join(root, name), limits[name]);
    if (!same(actual, expected[name]))
      throw fault('SDMX_EXPORT_CHANGED', 'The exported ' + name + ' differs from its saved SDMX lineage.', 409);
  }
  const config = (await jsonFile(join(root, 'dataset.json'), limits['dataset.json'])).value;
  if (config.schema !== 'stellar-forge.csv-dataset.v1' || !['data.csv', './data.csv'].includes(config.file))
    throw fault('SDMX_NATIVE_CONFIG_REQUIRED', 'Use the original self-contained SDMX dataset export.');
  return { root, lineage, project, expected, lineageFile };
}
async function writeNew(path, bytes) {
  const handle = await open(path, 'wx', 0o600);
  try { await handle.writeFile(bytes); await handle.sync(); } finally { await handle.close(); }
}
async function copyExact(source, target, expected, maximum) {
  const input = await open(source, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  let output;
  try {
    const before = await input.stat({ bigint: true });
    if (!before.isFile() || before.size !== BigInt(expected.bytes) || before.size > BigInt(maximum))
      throw fault('SDMX_EXPORT_CHANGED', 'The selected source file changed before publication.', 409);
    output = await open(target, 'wx', 0o600);
    const hash = createHash('sha256'); let bytes = 0;
    for await (const chunk of input.createReadStream({ autoClose: false })) {
      bytes += chunk.length;
      if (bytes > maximum) throw fault('SDMX_FILE_LIMIT', 'The source file exceeds its native limit.');
      hash.update(chunk); await output.writeFile(chunk);
    }
    if (identity(before) !== identity(await input.stat({ bigint: true })) ||
        bytes !== expected.bytes || hash.digest('hex') !== expected.sha256)
      throw fault('SDMX_EXPORT_CHANGED', 'The immutable SDMX source changed during publication.', 409);
    await output.sync();
  } finally { await output?.close(); await input.close(); }
}
async function installExact(source, target, expected, maximum) {
  try { await link(source, target); }
  catch (error) {
    if (error.code !== 'EEXIST') throw error;
    if (!same(await inspectFile(target, maximum), expected))
      throw fault('SDMX_RELEASE_CONFLICT', 'The selected release directory contains different retained bytes.', 409);
  }
}

/** A release contains the reviewed projection, lineage and the original seller
 * configuration. The complete source packet remains the workspace's own export. */
export async function prepareSdmxMerchant({ datasetDirectory, directory, payment, origin, path = '/sdmx' } = {}) {
  if (typeof datasetDirectory !== 'string' || typeof directory !== 'string')
    throw new TypeError('A native dataset export and a release directory are required.');
  const projection = await readProjection(datasetDirectory);
  const dataset = await loadDatasetConfig(join(projection.root, 'dataset.json'));
  const description = dataset.describe();
  if (description.snapshot !== projection.lineage.snapshot)
    throw fault('SDMX_SNAPSHOT_CHANGED', 'The original dataset engine returned a different saved SDMX snapshot.', 409);
  const config = await buildDatasetSellerConfig(dataset, { payment, origin, path });
  const parameters = config.routes[0].definition.queryParameters;
  if (parameters.length >= 32)
    throw fault('SDMX_SNAPSHOT_PARAMETER_REQUIRED', 'Retain one native query-parameter slot for the exact edition selector.');
  parameters.push({ ...DATASET_SNAPSHOT_PARAMETER });
  const sellerBytes = encode(config);
  const files = { ...projection.expected,
    'sdmx-lineage.json': { bytes: projection.lineageFile.file.bytes, sha256: projection.lineageFile.file.sha256 },
    'seller.json': { bytes: sellerBytes.length, sha256: digest(sellerBytes) } };
  const manifest = { schema: SDMX_MERCHANT_RELEASE_SCHEMA, project: projection.project,
    snapshot: description.snapshot, resource: config.publicOrigin + config.routes[0].path,
    dataset: description, files, sources: projection.lineage.sources,
    selection: projection.lineage.selection, created_at: projection.lineage.created_at };
  manifest.id = releaseIdentity(manifest);
  const manifestBytes = encode(manifest), root = resolve(directory);
  await privateDirectory(dirname(root));
  const temporary = join(dirname(root), '.sdmx-release-' + randomUUID());
  await mkdir(temporary, { mode: 0o700 });
  try {
    for (const name of ['data.csv', 'dataset.json', 'sdmx-lineage.json'])
      await copyExact(join(projection.root, name), join(temporary, name), files[name], limits[name]);
    await writeNew(join(temporary, 'seller.json'), sellerBytes);
    await writeNew(join(temporary, 'release.json'), manifestBytes);
    try { await mkdir(root, { mode: 0o700 }); }
    catch (error) { if (error.code !== 'EEXIST') throw error; }
    const info = await lstat(root);
    if (!info.isDirectory() || info.isSymbolicLink())
      throw fault('SDMX_RELEASE_CONFLICT', 'Select a regular release directory.', 409);
    // The create-only manifest binds an interrupted preparation before the
    // remaining immutable members are linked. A matching retry fills only gaps.
    await installExact(join(temporary, 'release.json'), join(root, 'release.json'),
      { bytes: manifestBytes.length, sha256: digest(manifestBytes) }, 8 * 1024 * 1024);
    for (const name of DATA_FILES)
      await installExact(join(temporary, name), join(root, name), files[name], limits[name]);
    await syncDirectory(root);
    const saved = await readSdmxMerchant(root);
    return { directory: root, manifest: saved.manifest, seller: join(root, 'seller.json'),
      dataset: join(root, 'dataset.json'), lineage: join(root, 'sdmx-lineage.json') };
  } finally { await rm(temporary, { recursive: true, force: true }); }
}

export async function readSdmxMerchant(directory) {
  const root = resolve(directory), manifest = (await jsonFile(join(root, 'release.json'), 8 * 1024 * 1024)).value;
  if (!object(manifest) || manifest.schema !== SDMX_MERCHANT_RELEASE_SCHEMA ||
      !HASH.test(manifest.id ?? '') || !HASH.test(manifest.snapshot ?? '') ||
      manifest.id !== releaseIdentity(manifest) || !object(manifest.files) ||
      Object.keys(manifest.files).sort().join('|') !== [...DATA_FILES].sort().join('|'))
    throw fault('SDMX_RELEASE_INVALID', 'The original SDMX merchant release identity is invalid.');
  projectIdentity(manifest.project);
  for (const name of DATA_FILES) {
    const expected = fileIdentity(manifest.files[name], limits[name]);
    if (!same(await inspectFile(join(root, name), limits[name]), expected))
      throw fault('SDMX_RELEASE_CHANGED', 'A retained SDMX merchant file differs from its release.', 409);
  }
  const config = (await jsonFile(join(root, 'seller.json'), limits['seller.json'])).value;
  if (config.publicOrigin + config.routes?.[0]?.path !== manifest.resource)
    throw fault('SDMX_RELEASE_CHANGED', 'The release resource differs from its original seller configuration.', 409);
  const lineage = (await jsonFile(join(root, 'sdmx-lineage.json'), limits['sdmx-lineage.json'])).value;
  if (!object(lineage) || !object(lineage.files) || lineage.schema !== 'stellar-forge.sdmx-lineage.v1' || lineage.snapshot !== manifest.snapshot ||
      !same(projectIdentity(lineage.project), manifest.project) ||
      !same(lineage.files['data.csv'], manifest.files['data.csv']) ||
      !same(lineage.files['dataset.json'], manifest.files['dataset.json']))
    throw fault('SDMX_RELEASE_CHANGED', 'The retained projection lineage differs from this release.', 409);
  return { directory: root, manifest, config, lineage, configPath: join(root, 'dataset.json') };
}
function bindingFor(release) {
  return { schema: BINDING_SCHEMA, project_id: release.manifest.project.id,
    seller_sha256: release.manifest.files['seller.json'].sha256, resource: release.manifest.resource };
}
async function readBinding(directory, release) {
  const value = (await jsonFile(join(resolve(directory), 'sdmx-merchant-binding.json'), 16384)).value;
  if (!same(value, bindingFor(release)))
    throw fault('SDMX_SELLER_BINDING_CHANGED', 'Use the same original project, route and public payment terms for a dataset refresh.', 409);
  return value;
}
async function saveBinding(directory, release) {
  const path = join(directory, 'sdmx-merchant-binding.json'), bytes = encode(bindingFor(release));
  const temporary = join(directory, '.sdmx-binding-' + randomUUID());
  try {
    await writeNew(temporary, bytes);
    await installExact(temporary, path, { bytes: bytes.length, sha256: digest(bytes) }, 16384);
    await syncDirectory(directory);
  } finally { await rm(temporary, { force: true }); }
}
async function nativeFactoryFor(facilitator, allowLocalFacilitator) {
  if (!facilitator) {
    if (allowLocalFacilitator) throw new TypeError('A facilitator URL is required for the explicit local option.');
    return null;
  }
  const url = new URL(facilitator);
  const local = allowLocalFacilitator && url.protocol === 'http:' && url.hostname === '127.0.0.1';
  if ((!local && url.protocol !== 'https:') || url.username || url.password || url.search || url.hash)
    throw new TypeError('Select the original HTTPS facilitator, or explicitly allow its loopback HTTP address.');
  const [{ HTTPFacilitatorClient }, { createNativeSellerServer }] = await Promise.all([
    import('@x402/core/server'), import('../native-factory.mjs'),
  ]);
  return compiled => createNativeSellerServer(compiled, {
    facilitatorClient: new HTTPFacilitatorClient({ url: url.href.replace(/\/$/, '') }) });
}

/** Start the existing versioned seller. Its one writer lease, request lifetime,
 * control transport, native verification and shutdown remain authoritative. */
export async function startSdmxMerchant({ directory, stateDirectory, port = 8423,
  retentionSeconds = 3600, maxVersions = 4, maxRetainedBytes = 268435456,
  maxCachedVersions = 2, maxResidentRows = 1000000, maxInFlight = 64, drainGraceMs = 60000,
  controlTransport = 'unix', facilitator, allowLocalFacilitator = false, nativeFactory } = {}) {
  if (typeof stateDirectory !== 'string') throw new TypeError('The original private version-state directory is required.');
  const release = await readSdmxMerchant(directory), state = resolve(stateDirectory);
  const initialized = await exists(join(state, 'state.json'));
  const bound = initialized && await exists(join(state, 'sdmx-merchant-binding.json'));
  if (bound) await readBinding(state, release);
  const versions = await openDatasetVersions({ directory: state, maxCachedVersions, maxResidentRows,
    ...(!initialized ? { initialConfig: release.configPath,
      retentionMs: count(retentionSeconds, 'retentionSeconds') * 1000,
      maxVersions, maxRetainedBytes } : {}) });
  try {
    if (!bound && versions.status().current !== release.manifest.snapshot)
      throw fault('SDMX_SELLER_BINDING_CHANGED', 'The existing unbound store has a different selected dataset.', 409);
    const route = release.config.routes[0];
    const expectedConfig = await buildDatasetSellerConfig(versions, {
      payment: route.definition.payment, origin: release.config.publicOrigin, path: route.path });
    expectedConfig.routes[0].definition.queryParameters.push({ ...DATASET_SNAPSHOT_PARAMETER });
    if (!same(expectedConfig, release.config))
      throw fault('SDMX_SELLER_CONTRACT_CHANGED', 'The version store and original seller have different advertised dataset contracts.', 409);
    await saveBinding(state, release);
    const factory = nativeFactory === undefined ? await nativeFactoryFor(facilitator, allowLocalFacilitator) : nativeFactory;
    const service = await startVersionedDatasetSeller({ versions, config: release.config, port,
      nativeFactory: factory, controlTransport, maxInFlight, drainGraceMs });
    return { ...service, release: release.manifest, stateDirectory: state };
  } catch (error) { await versions.close(); throw error; }
}

/** Publication uses the original running seller's serialized CAS, preserving
 * the public price and query contract while changing its retained observations. */
export async function publishSdmxMerchant({ directory, stateDirectory, expectedSnapshot, expectedRevision } = {}) {
  const release = await readSdmxMerchant(directory);
  await readBinding(stateDirectory, release);
  if (!HASH.test(expectedSnapshot ?? '')) throw new TypeError('Select the original current snapshot from status.');
  count(expectedRevision, 'expectedRevision');
  const result = await datasetControl(stateDirectory, 'refresh', {
    configPath: release.configPath, expectedSnapshot, expectedRevision });
  if (result.current !== release.manifest.snapshot)
    throw fault('SDMX_PUBLICATION_MISMATCH', 'Inspect the original version store; its current snapshot differs from the selected release.', 409);
  return { release: release.manifest.id, project: release.manifest.project, ...result };
}

const HELP = [
  'SDMX original merchant release',
  'prepare --dataset EXPORTED_NATIVE_DIR --payment PUBLIC_TERMS.json --origin HTTPS_ORIGIN --out RELEASE_DIR [--path /sdmx]',
  'inspect --release RELEASE_DIR',
  'serve --release RELEASE_DIR --state PRIVATE_STATE [--port 8423] [--facilitator HTTPS_URL]',
  '      [--allow-local-facilitator] [--control-transport unix|loopback]',
  '      [--retention-seconds 3600] [--max-versions 4] [--max-retained-bytes 268435456]',
  '      [--max-cached-versions 2] [--max-resident-rows 1000000] [--max-in-flight 64] [--drain-grace-ms 60000]',
  'status --state PRIVATE_STATE',
  'publish --release RELEASE_DIR --state PRIVATE_STATE --expect CURRENT_SHA --expect-revision REVISION',
  'activate --state PRIVATE_STATE --snapshot RETAINED_SHA --expect CURRENT_SHA --expect-revision REVISION',
  'collect --state PRIVATE_STATE',
  'Preparation retains exact projected CSV, native configuration, SDMX lineage and explicit public terms.',
  'The original dataset seller owns publication, admission, payment processing, retention and recovery.',
].join('\n') + '\n';
function parse(args) {
  const [action, ...tokens] = args;
  const common = ['--state'];
  const allowed = {
    prepare: ['--dataset', '--payment', '--origin', '--out', '--path'],
    inspect: ['--release'],
    serve: ['--release', '--state', '--port', '--facilitator', '--allow-local-facilitator', '--control-transport',
      '--retention-seconds', '--max-versions', '--max-retained-bytes', '--max-cached-versions',
      '--max-resident-rows', '--max-in-flight', '--drain-grace-ms'],
    status: common, publish: [...common, '--release', '--expect', '--expect-revision'],
    activate: [...common, '--snapshot', '--expect', '--expect-revision'], collect: common,
  }[action];
  if (!allowed) throw new TypeError(HELP);
  const flags = {};
  for (let index = 0; index < tokens.length; index++) {
    const key = tokens[index];
    if (!allowed.includes(key) || Object.hasOwn(flags, key)) throw new TypeError('Unknown or duplicate merchant option: ' + key);
    if (key === '--allow-local-facilitator') { flags[key] = true; continue; }
    if (!tokens[index + 1] || tokens[index + 1].startsWith('--')) throw new TypeError('Missing value for ' + key);
    flags[key] = tokens[++index];
  }
  return { action, flags };
}
function required(flags, name) {
  if (!flags[name]) throw new TypeError(name + ' is required.');
  return flags[name];
}
function number(flags, name, fallback) {
  if (flags[name] === undefined) return fallback;
  if (!/^(0|[1-9][0-9]*)$/.test(flags[name])) throw new TypeError(name + ' must be an integer.');
  return count(Number(flags[name]), name, 0);
}
const print = value => process.stdout.write(JSON.stringify(value, null, 2) + '\n');
export async function main(args = process.argv.slice(2)) {
  if (!args.length || args.length === 1 && ['help', '--help'].includes(args[0])) { process.stdout.write(HELP); return; }
  const { action, flags: f } = parse(args);
  if (action === 'prepare') return print(await prepareSdmxMerchant({
    datasetDirectory: required(f, '--dataset'), directory: required(f, '--out'),
    payment: (await jsonFile(required(f, '--payment'), 16384)).value,
    origin: required(f, '--origin'), path: f['--path'] ?? '/sdmx' }));
  if (action === 'inspect') {
    const release = await readSdmxMerchant(required(f, '--release'));
    return print({ directory: release.directory, manifest: release.manifest });
  }
  const stateDirectory = required(f, '--state');
  if (action === 'status' || action === 'collect') return print(await datasetControl(stateDirectory, action));
  if (action === 'publish') return print(await publishSdmxMerchant({
    directory: required(f, '--release'), stateDirectory,
    expectedSnapshot: required(f, '--expect'), expectedRevision: number(f, '--expect-revision') }));
  if (action === 'activate') return print(await datasetControl(stateDirectory, 'activate', {
    snapshot: required(f, '--snapshot'), expectedSnapshot: required(f, '--expect'),
    expectedRevision: count(number(f, '--expect-revision'), '--expect-revision') }));
  const service = await startSdmxMerchant({
    directory: required(f, '--release'), stateDirectory, port: number(f, '--port', 8423),
    retentionSeconds: number(f, '--retention-seconds', 3600), maxVersions: number(f, '--max-versions', 4),
    maxRetainedBytes: number(f, '--max-retained-bytes', 268435456),
    maxCachedVersions: number(f, '--max-cached-versions', 2), maxResidentRows: number(f, '--max-resident-rows', 1000000),
    maxInFlight: number(f, '--max-in-flight', 64), drainGraceMs: number(f, '--drain-grace-ms', 60000),
    controlTransport: f['--control-transport'] ?? 'unix', facilitator: f['--facilitator'],
    allowLocalFacilitator: f['--allow-local-facilitator'] ?? false });
  print({ url: service.url, mode: service.mode, release: service.release.id,
    project: service.release.project, stateDirectory: service.stateDirectory,
    current: service.versions.status().current, health: service.url + '/_seller/health',
    offers: service.url + '/_seller/offers', docs: service.url + '/_seller/docs' });
  let stopping = false;
  const stop = () => {
    if (stopping) return; stopping = true;
    service.close().catch(error => { process.stderr.write('SDMX merchant: ' + error.message + '\n'); process.exitCode = 1; });
  };
  process.once('SIGINT', stop); process.once('SIGTERM', stop);
  return service;
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { process.stderr.write(JSON.stringify({ error: error.code ?? 'SDMX_MERCHANT', message: error.message }) + '\n'); process.exitCode = 1; });

"""MIT. Private local SDMX operator console over the retained Workspace and SF30 engine.

The process gate, bounded streaming reader, request slots and static policy follow
the original SF30 XML operator at fe011df4. The Workspace owns all data semantics.
"""
from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import secrets
import shutil
import threading
from urllib.parse import parse_qs, unquote, urlsplit
import zipfile

from sdmx_workspace import Workspace, InputError, MAX_SOURCE, MAX_PACKET, json_bytes, load_json

HERE = Path(__file__).resolve().parent


class LimitedReader:
    def __init__(self, source, length: int):
        self.source, self.remaining = source, length

    def read(self, size: int = -1):
        if self.remaining == 0:
            return b""
        block = self.source.read(min(self.remaining, size if size >= 0 else self.remaining))
        if not block:
            raise InputError("Upload ended before its declared content length")
        self.remaining -= len(block)
        return block


class OperatorServer(ThreadingHTTPServer):
    daemon_threads = False
    block_on_close = True

    def __init__(self, workspace: Workspace, port: int = 0):
        self.workspace, self.token = workspace, secrets.token_urlsafe(32)
        self.slots = threading.BoundedSemaphore(8)
        super().__init__(("127.0.0.1", port), Handler)
        self.origin = f"http://127.0.0.1:{self.server_port}"
        self.url = self.origin + "/#" + self.token

    def process_request(self, request, client_address):
        if not self.slots.acquire(blocking=False):
            self.shutdown_request(request)
            return
        try:
            super().process_request(request, client_address)
        except Exception:
            self.slots.release()
            raise

    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            self.slots.release()


class Handler(BaseHTTPRequestHandler):
    server_version = "SF30-SDMX"
    protocol_version = "HTTP/1.0"

    def setup(self):
        super().setup()
        self.connection.settimeout(60)

    def log_message(self, *_):
        pass

    def _gate(self, api: bool = True):
        target = urlsplit(self.path)
        if len(self.headers.get_all("Host", [])) != 1 or len(self.headers.get_all("Origin", [])) > 1:
            raise PermissionError("Repeated local origin or host headers are not accepted")
        if target.scheme or target.netloc or self.headers.get("Host") != urlsplit(self.server.origin).netloc:
            raise PermissionError("Invalid local host")
        if self.headers.get("Origin") not in {None, self.server.origin}:
            raise PermissionError("Cross-origin requests are not accepted")
        if api:
            supplied = self.headers.get("Authorization", "")
            if not secrets.compare_digest(supplied.encode(), ("Bearer " + self.server.token).encode()):
                raise PermissionError("Open this process's private console link")
        return target

    def _headers(self, status, content_type, length, filename=None):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Resource-Policy", "same-origin")
        self.send_header("Content-Security-Policy", "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
        if filename:
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
        self.end_headers()

    def _json(self, value, status=200):
        data = json_bytes(value)
        self._headers(status, "application/json; charset=utf-8", len(data))
        self.wfile.write(data)

    def _body(self, maximum=131072):
        raw = self.headers.get("Content-Length", "")
        if self.headers.get("Transfer-Encoding") or len(self.headers.get_all("Content-Length", [])) != 1 or not raw.isdecimal():
            raise InputError("A single Content-Length is required")
        length = int(raw)
        if length > maximum:
            raise InputError("Request exceeds its size limit")
        return LimitedReader(self.rfile, length)

    def _query(self, target):
        values = parse_qs(target.query, keep_blank_values=True)
        if any(len(items) != 1 for items in values.values()):
            raise InputError("Repeated query parameters are not accepted")
        return {key: items[0] for key, items in values.items()}

    def _integer(self, query, key, default, minimum=0, maximum=100000000):
        raw = query.get(key, str(default))
        if not raw.isdecimal():
            raise InputError(f"{key} must be a nonnegative integer")
        value = int(raw)
        if not minimum <= value <= maximum:
            raise InputError(f"{key} is outside its supported range")
        return value

    def _revision(self, values, key="revision"):
        value = values.get(key)
        if value is None or value == "":
            return None
        if isinstance(value, bool):
            raise InputError("Revision must be a positive integer")
        try:
            revision = int(value)
        except (TypeError, ValueError) as error:
            raise InputError("Revision must be a positive integer") from error
        if revision < 1 or str(revision) != str(value):
            raise InputError("Revision must be a positive integer")
        return revision

    def _download(self, path: Path, filename: str, media="application/octet-stream"):
        with path.open("rb") as stream:
            self._headers(200, media, path.stat().st_size, filename)
            shutil.copyfileobj(stream, self.wfile, 65536)

    def _run(self, callback):
        try:
            callback()
        except PermissionError as error:
            self._json({"error": str(error)}, 403)
        except (InputError, ValueError, KeyError, zipfile.BadZipFile) as error:
            status = getattr(error, "status", 400)
            self._json({"error": str(error)}, status if status in {400, 409, 413, 422} else 400)
        except FileNotFoundError:
            self._json({"error": "Retained source, project or comparison was not found"}, 404)
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            pass
        except Exception:
            self._json({"error": "The local operation failed; the retained workspace remains available"}, 500)

    def do_GET(self):
        self._run(self._get)

    def _get(self):
        target = self._gate(api=False)
        assets = {
            "/": ("index.html", "text/html; charset=utf-8"),
            "/app.js": ("app.js", "text/javascript; charset=utf-8"),
            "/style.css": ("style.css", "text/css; charset=utf-8"),
        }
        if target.path in assets:
            name, media = assets[target.path]
            data = (HERE / "public" / name).read_bytes()
            self._headers(200, media, len(data))
            self.wfile.write(data)
            return
        self._gate()
        query = self._query(target)
        ws = self.server.workspace
        if target.path == "/api/state":
            self._json(ws.state())
            return
        parts = target.path.strip("/").split("/")
        if len(parts) in {3, 4} and parts[:2] == ["api", "sources"]:
            source_id = parts[2]
            if len(parts) == 3:
                self._json(ws.source(source_id))
            elif parts[3] == "series":
                self._json(ws.series(source_id, self._integer(query, "offset", 0),
                                     self._integer(query, "limit", 50, 1, 200), query.get("query", "")))
            elif parts[3] == "observations":
                self._json(ws.observations(source_id, query.get("series_key") or None,
                    self._integer(query, "offset", 0), self._integer(query, "limit", 50, 1, 200)))
            else:
                self._json({"error": "Unknown local route"}, 404)
            return
        if len(parts) in {3, 4} and parts[:2] == ["api", "projects"]:
            project_id = parts[2]
            revision = self._revision(query)
            if len(parts) == 3:
                self._json(ws.project(project_id, revision))
            elif parts[3] in {"dataset", "packet"}:
                with ws.mutex, ws.scratch() as temporary:
                    if parts[3] == "packet":
                        archive = temporary / "sdmx-project.zip"
                        ws.export_packet(project_id, archive, revision)
                    else:
                        folder = temporary / "dataset"
                        ws.export_dataset(project_id, folder, revision)
                        archive = temporary / "sf30-sdmx-dataset.zip"
                        with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED) as output:
                            for name in ["data.csv", "dataset.json", "sdmx-lineage.json"]:
                                output.write(folder / name, name)
                        archive.chmod(0o600)
                    self._download(archive, archive.name, "application/zip")
            else:
                self._json({"error": "Unknown local route"}, 404)
            return
        if len(parts) == 3 and parts[:2] == ["api", "comparisons"]:
            self._json(ws.comparison_page(parts[2], self._integer(query, "offset", 0),
                                         self._integer(query, "limit", 50, 1, 200)))
            return
        self._json({"error": "Unknown local route"}, 404)

    def do_POST(self):
        self._run(self._post)

    def _post(self):
        target = self._gate()
        ws = self.server.workspace
        if target.path == "/api/sources/upload":
            name = unquote(self.headers.get("X-SDMX-Name", "source.xml"))
            metadata = {
                "name": name,
                "label": unquote(self.headers.get("X-SDMX-Label", name)),
                "origin": unquote(self.headers.get("X-SDMX-Origin", "")),
                "kind": unquote(self.headers.get("X-SDMX-Kind", "auto")),
            }
            media_type = self.headers.get("Content-Type")
            if media_type:
                metadata["media_type"] = media_type.split(";", 1)[0].strip()
            self._json(ws.add_source(self._body(MAX_SOURCE), metadata), 201)
            return
        if target.path == "/api/import":
            with ws.mutex, ws.scratch() as temporary:
                packet = temporary / "input.zip"
                with packet.open("xb") as output:
                    packet.chmod(0o600)
                    shutil.copyfileobj(self._body(MAX_PACKET), output, 65536)
                result = ws.import_packet(packet)
            self._json(result, 201)
            return
        body = load_json(self._body().read())
        if not isinstance(body, dict):
            raise InputError("Expected a JSON object")
        if target.path == "/api/projects":
            self._json(ws.save_project(body), 201)
        elif target.path == "/api/query":
            params = body.get("params", {})
            if not isinstance(params, dict):
                raise InputError("Native query parameters must be an object")
            self._json(ws.query(body["project_id"], params, self._revision(body)))
        elif target.path == "/api/comparisons":
            self._json(ws.compare(body["before_project"], body["after_project"],
                self._revision(body, "before_revision"), self._revision(body, "after_revision")), 201)
        else:
            self._json({"error": "Unknown local route"}, 404)

"""MIT. Lossless SDMX 2.1 structures, generic/specific observations and ECB CSV."""
from __future__ import annotations

import csv
from datetime import date, timedelta
import hashlib
import json
from pathlib import Path
import re
import sys
from urllib.parse import urlparse, parse_qs, unquote

XML = Path(__file__).resolve().parent.parent / "xml"
if str(XML) not in sys.path:
    sys.path.insert(0, str(XML))
from xml_source import InputError, MAX_SOURCE, MAX_RECORD, MAX_DEPTH, parser, parse_stream, expanded

NS = "http://www.sdmx.org/resources/sdmxml/schemas/v2_1/"
LANG = "{http://www.w3.org/XML/1998/namespace}lang"
MAINTAINABLES = {"Dataflow", "DataStructure", "Codelist", "ConceptScheme", "CategoryScheme",
                "ContentConstraint", "ProvisionAgreement", "AgencyScheme", "HierarchicalCodelist"}
MAX_OBSERVATIONS = 1000000
MAX_METADATA = 32 * 1024 * 1024
MAX_CELL = 1048576


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def sha(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def local(name):
    return name.rsplit("}", 1)[-1]


def children(node, name):
    return [n for n in node["children"] if local(n["tag"]) == name]


def descendants(node, name):
    found = []
    for child in node["children"]:
        if local(child["tag"]) == name:
            found.append(child)
        found.extend(descendants(child, name))
    return found


def first(node, name):
    rows = descendants(node, name)
    return rows[0] if rows else None


def names(node):
    return [{"lang": n["attrs"].get(LANG, ""), "text": n["text"]}
            for n in children(node, "Name")]


def reference(node):
    if node is None:
        return {}
    ref = node if local(node["tag"]) == "Ref" else first(node, "Ref")
    if ref is not None:
        a = ref["attrs"]
        return {"id": a.get("id", ""), "agency_id": a.get("agencyID", ""),
                "version": a.get("version", a.get("maintainableParentVersion", "")),
                "parent_id": a.get("maintainableParentID", ""), "class": a.get("class", ""),
                "package": a.get("package", "")}
    urn_node = node if local(node["tag"]) == "URN" else first(node, "URN")
    if urn_node is None:
        return {}
    urn = urn_node["text"].strip()
    match = re.fullmatch(
        r"urn:sdmx:org\.sdmx\.infomodel\.([A-Za-z][A-Za-z0-9_.]*)\."
        r"([A-Za-z][A-Za-z0-9_]*)=([^:\s]+):([^()]+)\(([^()]+)\)(?:\.(.+))?", urn)
    if not match:
        return {"urn": urn}
    package, kind, agency, maintainable_id, version, item_id = match.groups()
    return {"id": item_id if item_id is not None else maintainable_id,
            "agency_id": agency, "version": version,
            "parent_id": maintainable_id if item_id is not None else "",
            "class": kind, "package": package, "urn": urn}


def descriptor(node):
    a, n = node["attrs"], names(node)
    return {"id": a["id"], "agency_id": a.get("agencyID", ""),
            "version": a.get("version", ""), "name": next(
                (x["text"] for x in n if x["lang"] == "en"), n[0]["text"] if n else a["id"]),
            "names": n, "attributes": dict(a), "raw_attributes": dict(a),
            "descriptions": [{"lang": d["attrs"].get(LANG, ""), "text": d["text"]}
                             for d in children(node, "Description")]}


def component(node, role=None):
    a = node["attrs"]
    out = {"id": a.get("id", ""), "concept": reference(first(node, "ConceptIdentity")),
           "codelist": reference(first(node, "Enumeration"))}
    if role:
        out.update(position=int(a.get("position", "0")), role=role)
    if local(node["tag"]) == "Attribute":
        relation = first(node, "AttributeRelationship")
        out.update(assignment_status=a.get("assignmentStatus", ""),
                   relationship={"kind": local(relation["children"][0]["tag"]) if relation and relation["children"] else "",
                                 "dimensions": [reference(x).get("id") for x in children(relation, "Dimension")] if relation else [],
                                 "content": relation})
    formats = descendants(node, "TextFormat")
    if formats:
        out["text_format"] = formats[0]["attrs"]
    return out


def maintained(node, result):
    kind = local(node["tag"])
    item = descriptor(node)
    if kind == "Dataflow":
        item["structure"] = reference(first(node, "Structure"))
        result["flows"].append(item)
    elif kind == "DataStructure":
        dims = first(node, "DimensionList")
        item["dimensions"] = sorted(
            [component(n, {"TimeDimension": "time", "MeasureDimension": "measure"}.get(local(n["tag"]), "dimension"))
             for n in dims["children"] if local(n["tag"]) in {"Dimension", "TimeDimension", "MeasureDimension"}] if dims else [],
            key=lambda x: x["position"])
        attrs = first(node, "AttributeList")
        measures = first(node, "MeasureList")
        item["attributes"] = [component(n) for n in attrs["children"] if local(n["tag"]) == "Attribute"] if attrs else []
        item["measures"] = [component(n) for n in measures["children"] if local(n["tag"]) in {"PrimaryMeasure", "MeasureDimension"}] if measures else []
        item["groups"] = [{"id": n["attrs"].get("id", ""),
                           "dimensions": [reference(x).get("id") for x in children(n, "GroupDimension")]}
                          for n in descendants(node, "Group")]
        result["structures"].append(item)
        result["dimensions"].extend(item["dimensions"])
    elif kind == "Codelist":
        item["codes"] = []
        for code in children(node, "Code"):
            ns = names(code)
            item["codes"].append({"id": code["attrs"].get("id", ""),
                "name": next((x["text"] for x in ns if x["lang"] == "en"), ns[0]["text"] if ns else code["attrs"].get("id", "")),
                "names": ns, "parent": reference(first(code, "Parent")),
                "descriptions": [{"lang": d["attrs"].get(LANG, ""), "text": d["text"]} for d in children(code, "Description")]})
        result["codelists"].append(item)
    else:
        result["other_structures"].append({"kind": kind, **item, "content": node})


def coverage(origin, supplied=None):
    result = {"origin": origin, "selection": {}, "completeness": "unspecified",
              "start_period": None, "end_period": None, "updated_after": None}
    if origin:
        url = urlparse(origin)
        args = parse_qs(url.query, keep_blank_values=True)
        selection = {k: v for k, v in sorted(args.items()) if k not in {"format", "updatedAfter"}}
        parts = url.path.rstrip("/").split("/")
        if "data" in parts:
            at = parts.index("data")
            result["flow"] = unquote(parts[at + 1]) if len(parts) > at + 1 else ""
            raw = unquote(parts[at + 2]) if len(parts) > at + 2 else ""
            result["key"] = ".".join("+".join(sorted(p.split("+"))) for p in raw.split("."))
            result["selection"] = {"flow": result["flow"], "key": result["key"], "query": selection}
            result["start_period"] = (args.get("startPeriod") or [None])[0]
            result["end_period"] = (args.get("endPeriod") or [None])[0]
            result["updated_after"] = (args.get("updatedAfter") or [None])[0]
            result["completeness"] = "partial_update" if result["updated_after"] else "selected_response"
            if any(k in args for k in ("firstNObservations", "lastNObservations")):
                result["completeness"] = "limited_response"
    if supplied is not None:
        if not isinstance(supplied, dict) or set(supplied) - {"start_period", "end_period", "updated_after", "completeness", "selection", "receipt"}:
            raise InputError("Unsupported source coverage fields")
        result.update(supplied)
    return result


def period_bounds(value, frequency):
    """Return declared calendar bounds without resampling or altering a source value."""
    try:
        if re.fullmatch(r"\d{4}", value) and frequency == "A":
            y = int(value)
            return date(y, 1, 1).isoformat(), date(y, 12, 31).isoformat()
        match = re.fullmatch(r"(\d{4})-([QS])([1-4])", value)
        if match:
            y, kind, n = int(match[1]), match[2], int(match[3])
            if (kind == "Q" and frequency == "Q") or (kind == "S" and frequency in {"H", "S"} and n <= 2):
                width = 3 if kind == "Q" else 6
                month = (n - 1) * width + 1
                start = date(y, month, 1)
                end = date(y + (month + width > 12), (month + width - 1) % 12 + 1, 1) - timedelta(days=1)
                return start.isoformat(), end.isoformat()
        if re.fullmatch(r"\d{4}-\d{2}", value) and frequency == "M":
            y, m = map(int, value.split("-"))
            start = date(y, m, 1)
            end = date(y + (m == 12), m % 12 + 1, 1) - timedelta(days=1)
            return start.isoformat(), end.isoformat()
        match = re.fullmatch(r"(\d{4})-W(\d{2})", value)
        if match and frequency == "W":
            start = date.fromisocalendar(int(match[1]), int(match[2]), 1)
            return start.isoformat(), (start + timedelta(days=6)).isoformat()
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value) and frequency in {"D", "B"}:
            day = date.fromisoformat(value).isoformat()
            return day, day
    except (ValueError, OverflowError):
        pass
    return None, None


def parse_xml(path, on_series, on_observation, on_group):
    result = {"format": None, "kind": "data", "flows": [], "structures": [], "codelists": [],
              "dimensions": [], "other_structures": [], "header": None, "header_references": [], "datasets": [],
              "observation_count": 0}
    p, stack = parser(), []
    captured = []
    capture_bytes = 0
    metadata_bytes = 0
    dataset = series = group = obs = None
    serial = 0
    root_name = None

    def put(target, key, value):
        if not key or len(key) > 2048 or not isinstance(value, str) or len(value) > MAX_CELL:
            raise InputError("SDMX component exceeds the supported identifier or value size")
        if key in target and target[key] != value:
            raise InputError("SDMX repeats a component with different values: " + key)
        target[key] = value

    def series_record(active, count):
        dims = active["dimensions"]
        raw = active["raw_attributes"]
        ident = sha({"dataset": dataset["id"], "dimensions": dims, "raw": raw if not dims else {}})
        return {"id": ident, "dataset_id": dataset["id"],
                "series_key": ".".join(dims.values()) if dims else ident,
                "dimensions": dict(dims), "attributes": dict(active["attributes"]),
                "raw_attributes": dict(raw), "observation_count": count,
                "format": result["format"]}

    def start(raw_name, raw_attrs):
        nonlocal dataset, series, group, obs, capture_bytes, root_name
        name = expanded(raw_name)
        tag = local(name)
        attrs = {expanded(k): v for k, v in raw_attrs.items()}
        if len(stack) >= MAX_DEPTH or len(attrs) > 256 or len(name) > 2048:
            raise InputError("SDMX exceeds the XML depth or component limits")
        if any(len(k) > 2048 or len(v) > MAX_CELL for k, v in attrs.items()):
            raise InputError("SDMX XML attribute exceeds the supported size")
        if not stack:
            if name != "{" + NS + "message}" + tag or tag not in {"Structure", "GenericData", "StructureSpecificData"}:
                raise InputError("Use SDMX 2.1 Structure, GenericData or StructureSpecificData XML")
            root_name = tag
            result["format"] = {"Structure": "sdmx-structure-2.1", "GenericData": "sdmx-generic-2.1",
                                "StructureSpecificData": "sdmx-specific-2.1"}[tag]
            result["kind"] = "structure" if tag == "Structure" else "data"
        parent = stack[-1] if stack else None
        stack.append(tag)
        if captured or (tag == "Header" and len(stack) == 2) or (tag in MAINTAINABLES and attrs.get("id") and attrs.get("agencyID")):
            node = {"tag": name, "attrs": attrs, "text": "", "children": []}
            if captured:
                captured[-1]["children"].append(node)
            captured.append(node)
            capture_bytes += len(name) + sum(len(k) + len(v) for k, v in attrs.items()) + 64
            if capture_bytes > MAX_METADATA:
                raise InputError("A maintained SDMX metadata component exceeds 32 MiB")
        if root_name == "Structure":
            return
        if tag == "DataSet":
            if dataset is not None:
                raise InputError("Nested SDMX datasets are invalid")
            def dataset_control(key, default=""):
                qualified = "{" + NS + "data/structurespecific}" + key
                value = attrs.get(qualified) if result["format"] == "sdmx-specific-2.1" else None
                if value is not None:
                    if key in attrs and attrs[key] != value:
                        raise InputError("SDMX repeats a dataset control with different values: " + key)
                    return value
                return attrs.get(key, default)
            dataset = {"id": str(len(result["datasets"]) + 1), "attributes": {},
                       "raw_attributes": attrs, "action": dataset_control("action", "Replace")}
            structure_ref = dataset_control("structureRef")
            links = [link for link in result["header_references"]
                     if link["structure_id"] == structure_ref]
            if not structure_ref and len(result["header_references"]) == 1:
                links = result["header_references"]
            if len(links) == 1:
                dataset["structure_reference"] = dict(links[0]["reference"])
                dataset["dimension_at_observation"] = links[0]["dimension_at_observation"]
            if dataset["action"] not in {"Append", "Replace", "Delete", "Information"}:
                raise InputError("Unknown SDMX dataset action: " + dataset["action"])
            result["datasets"].append(dataset)
        elif tag == "Series":
            if dataset is None or series is not None:
                raise InputError("SDMX Series is outside its dataset")
            series = {"dimensions": {}, "attributes": {}, "raw_attributes": attrs, "count": 0}
        elif tag == "Group":
            if dataset is None:
                raise InputError("SDMX Group is outside its dataset")
            group = {"dataset_id": dataset["id"], "key": {}, "attributes": {}, "raw_attributes": attrs}
        elif tag == "Obs":
            if dataset is None:
                raise InputError("SDMX observation is outside its dataset")
            obs = {"time_period": attrs.get("TIME_PERIOD"), "value": attrs.get("OBS_VALUE"),
                   "value_present": "OBS_VALUE" in attrs, "attributes": {}, "raw_attributes": attrs, "key": {}}
        elif tag == "Value" and parent in {"SeriesKey", "GroupKey", "ObsKey", "DataSetKey", "Attributes"}:
            key, value = attrs.get("id"), attrs.get("value", "")
            if parent == "SeriesKey" and series is not None:
                if series["count"]:
                    raise InputError("Series dimensions must precede observations")
                put(series["dimensions"], key, value)
            elif parent == "GroupKey" and group is not None:
                put(group["key"], key, value)
            elif parent == "ObsKey" and obs is not None:
                put(obs["key"], key, value)
            elif parent == "DataSetKey" and dataset is not None:
                put(dataset.setdefault("dimensions", {}), key, value)
            elif parent == "Attributes":
                target = obs if obs is not None else group if group is not None else series if series is not None else dataset
                if target is not None:
                    put(target["attributes"], key, value)
        elif tag == "ObsDimension" and obs is not None:
            obs["time_period"] = attrs.get("value")
        elif tag == "ObsValue" and obs is not None:
            obs["value_present"] = "value" in attrs
            obs["value"] = attrs.get("value")
            if attrs.get("{http://www.w3.org/2001/XMLSchema-instance}nil") in {"true", "1"}:
                obs["value"] = None

    def text(value):
        nonlocal capture_bytes
        if captured:
            captured[-1]["text"] += value
            capture_bytes += len(value.encode("utf-8"))
            if capture_bytes > MAX_METADATA:
                raise InputError("A maintained SDMX metadata component exceeds 32 MiB")

    def end(raw_name):
        nonlocal dataset, series, group, obs, serial, capture_bytes, metadata_bytes
        tag = local(expanded(raw_name))
        if root_name != "Structure":
            if tag == "Obs" and obs is not None:
                serial += 1
                if serial > MAX_OBSERVATIONS:
                    raise InputError("Source exceeds one million observations")
                dims = dict(series["dimensions"] if series else dataset.get("dimensions", {}))
                dims.update({k: v for k, v in obs["key"].items() if k != "TIME_PERIOD"})
                period = obs["time_period"] or obs["key"].get("TIME_PERIOD")
                if not isinstance(period, str) or not period or len(period) > 160:
                    raise InputError("Each observation needs its original TIME_PERIOD")
                active = series or {"dimensions": dims, "attributes": {}, "raw_attributes": {}}
                sr = series_record(active, 1)
                if not series:
                    on_series(sr)
                observation_attrs = dict(obs["attributes"])
                if result["format"] == "sdmx-specific-2.1":
                    observation_attrs.update({k: v for k, v in obs["raw_attributes"].items()
                                              if k not in {"TIME_PERIOD", "OBS_VALUE"}})
                on_observation({"ordinal": serial, "series_id": sr["id"], "dataset_id": dataset["id"],
                    "series_key": sr["series_key"], "time_period": period, "value": obs["value"],
                    "value_present": obs["value_present"], "attributes": observation_attrs,
                    "raw_attributes": dict(obs["raw_attributes"]), "action": dataset["action"],
                    "dimensions": dims, "format": result["format"]})
                if series:
                    series["count"] += 1
                obs = None
            elif tag == "Series" and series is not None:
                on_series(series_record(series, series["count"]))
                series = None
            elif tag == "Group" and group is not None:
                on_group(group)
                group = None
            elif tag == "DataSet":
                dataset = None
        if captured:
            node = captured.pop()
            if not captured:
                if tag == "Header":
                    result["header"] = node
                    result["header_references"] = [
                        {"structure_id": link["attrs"].get("structureID", ""),
                         "dimension_at_observation": link["attrs"].get("dimensionAtObservation", ""),
                         "reference": reference(link), "raw_attributes": dict(link["attrs"])}
                        for link in children(node, "Structure")]
                else:
                    maintained(node, result)
                metadata_bytes += capture_bytes
                capture_bytes = 0
                if metadata_bytes > MAX_METADATA:
                    raise InputError("Derived SDMX metadata exceeds 32 MiB")
        stack.pop()

    p.StartElementHandler, p.EndElementHandler, p.CharacterDataHandler = start, end, text
    with path.open("rb") as stream:
        parse_stream(p, stream)
    result["observation_count"] = serial
    if result["kind"] == "structure" and result["flows"] and not result["structures"]:
        result["kind"] = "catalog"
    return result


def parse_csv(path, on_series, on_observation, on_group):
    csv.field_size_limit(MAX_CELL)
    result = {"format": "sdmx-csv", "kind": "data", "flows": [], "structures": [], "codelists": [],
              "dimensions": [], "other_structures": [], "header": None, "header_references": [], "datasets": [],
              "observation_count": 0}
    structural = {"KEY", "DATAFLOW", "STRUCTURE", "STRUCTURE_ID", "ACTION"}
    datasets = {}
    with path.open("r", encoding="utf-8-sig", newline="") as stream:
        reader = csv.reader(stream)
        try:
            header = next(reader)
        except StopIteration:
            raise InputError("SDMX CSV is empty")
        if not header or len(header) != len(set(header)) or len(header) > 256:
            raise InputError("SDMX CSV needs distinct column names")
        if "TIME_PERIOD" not in header or "OBS_VALUE" not in header:
            raise InputError("SDMX CSV must contain TIME_PERIOD and OBS_VALUE")
        if any(not c or len(c) > 2048 for c in header):
            raise InputError("Invalid SDMX CSV column")
        time_at = header.index("TIME_PERIOD")
        dimension_names = [c for c in header[:time_at] if c not in structural and c != "OBS_VALUE"]
        if not dimension_names or "FREQ" not in dimension_names:
            raise InputError("SDMX CSV must place its declared series dimensions before TIME_PERIOD, including FREQ")
        result["csv_columns"] = header
        result["dimensions"] = [{"id": key, "position": i + 1, "role": "dimension", "codelist": {}}
                                for i, key in enumerate(dimension_names)]
        for ordinal, cells in enumerate(reader, 1):
            if ordinal > MAX_OBSERVATIONS:
                raise InputError("Source exceeds one million observations")
            if len(cells) != len(header):
                raise InputError(f"CSV row {ordinal + 1} has the wrong number of fields")
            row = dict(zip(header, cells))
            dims = {k: row[k] for k in dimension_names}
            if any(not v for v in dims.values()) or not row["TIME_PERIOD"]:
                raise InputError(f"CSV row {ordinal + 1} has an empty dimension or period")
            key = ".".join(dims.values())
            original_key = row.get("KEY", "")
            flow = row.get("STRUCTURE_ID") or row.get("DATAFLOW") or (
                original_key[:-(len(key) + 1)] if original_key.endswith("." + key) else "")
            if original_key and original_key not in {key, flow + "." + key}:
                raise InputError(f"CSV row {ordinal + 1}: KEY differs from its dimension columns")
            action = row.get("ACTION") or "Replace"
            action = {"A": "Append", "R": "Replace", "D": "Delete", "I": "Information"}.get(action, action)
            if action not in {"Append", "Replace", "Delete", "Information"}:
                raise InputError(f"CSV row {ordinal + 1}: unknown SDMX action")
            dataset_key = (flow, action)
            if dataset_key not in datasets:
                ds = {"id": str(len(datasets) + 1), "attributes": {},
                      "raw_attributes": {"flow": flow, "structure": row.get("STRUCTURE", "dataflow")},
                      "action": action}
                datasets[dataset_key] = ds
                result["datasets"].append(ds)
            ds = datasets[dataset_key]
            attrs = {k: v for k, v in row.items() if k not in structural and k not in dims
                     and k not in {"TIME_PERIOD", "OBS_VALUE"}}
            ident = sha({"dataset": ds["id"], "dimensions": dims, "raw": {}})
            on_series({"id": ident, "dataset_id": ds["id"], "series_key": key,
                       "dimensions": dims, "attributes": {}, "raw_attributes": {},
                       "observation_count": 1, "format": result["format"]})
            on_observation({"ordinal": ordinal, "series_id": ident, "dataset_id": ds["id"],
                            "series_key": key, "dimensions": dims, "time_period": row["TIME_PERIOD"],
                            "value": row["OBS_VALUE"], "value_present": True,
                            "attributes": attrs, "raw_attributes": {}, "action": action,
                            "format": result["format"]})
            result["observation_count"] = ordinal
    return result


def parse_source(path, metadata, on_series, on_observation, on_group):
    with path.open("rb") as stream:
        prefix = stream.read(4096).lstrip(b"\xef\xbb\xbf \t\r\n")
    if prefix.startswith(b"<"):
        result = parse_xml(path, on_series, on_observation, on_group)
    else:
        result = parse_csv(path, on_series, on_observation, on_group)
    requested = metadata.get("kind", "auto")
    if requested not in {"auto", "data", "structure", "catalog"}:
        raise InputError("Source kind must be auto, data, structure or catalog")
    if requested != "auto" and requested != result["kind"] and not (
            requested == "catalog" and result["kind"] == "structure" and result["flows"]):
        raise InputError("Uploaded source does not match its declared kind")
    result["coverage"] = coverage(metadata.get("origin", ""), metadata.get("coverage"))
    result["coverage"]["actions"] = sorted({d["action"] for d in result["datasets"]})
    return result

